#define FILTER_LOWSHELF 2

/**
 * Filter type: high shelf.
 */
#define FILTER_HIGHSHELF 3

/**
 * Filter type: low-pass.
 */
#define FILTER_LOWPASS 4

/**
 * Filter type: high-pass.
 */
#define FILTER_HIGHPASS 5

/**
 * Filter type: notch.
 */
#define FILTER_NOTCH 6

/**
 * Second-order (RBJ) all-pass.
 */
#define FILTER_ALLPASS 7

/**
 * First-order all-pass: frequency only.
 */
#define FILTER_ALLPASS1 8

/**
 * First-order low shelf: frequency + gain, no Q.
 */
#define FILTER_LOWSHELF1 9

/**
 * First-order high shelf: frequency + gain, no Q.
 */
#define FILTER_HIGHSHELF1 10

/**
 * Linkwitz Transform: freq = f0, q = Q0, gain carries fp in Hz, qp = target Q.
 */
#define FILTER_LINKWITZ_TRANSFORM 11

/**
 * First-order low pass (6 dB/oct): frequency only.
 */
#define FILTER_LOWPASS1 12

/**
 * First-order high pass (6 dB/oct): frequency only.
 */
#define FILTER_HIGHPASS1 13

/**
 * First crossover type (LR2 LP). Crossover types run 32..=63:
 * LR2/4/6/8 = 32..39, Butterworth 1..8 = 40..55, Bessel 2/4/6/8 = 56..63,
 * each pair LP = even, HP = odd.
 */
#define FILTER_XOVER_FIRST 32

/**
 * Filter type: the last crossover type.
 */
#define FILTER_XOVER_LAST 63

/**
 * Default Q (Butterworth), also the Linkwitz Transform target-Q default.
 */
#define DEFAULT_Q 0.707

/**
 * Array sizes and limits of the records (RP2350 maxima).
 *
 * Maximum channels in the wire format (inputs + outputs, RP2350).
 */
#define MAX_CHANNELS 17

/**
 * Maximum input channels (RP2350).
 */
#define MAX_INPUTS 8

/**
 * Maximum output channels (RP2350).
 */
#define MAX_OUTPUTS 9

/**
 * PEQ bands per channel that the firmware processes.
 */
#define BANDS_PER_CHANNEL 10

/**
 * PEQ band storage per channel in the wire layout.
 */
#define FIRMWARE_BANDS_PER_CHANNEL 12

/**
 * Crossover bands per output channel.
 */
#define MAX_XOVER_BANDS 4

/**
 * Wire band index of crossover band 0 (crossover bands are 20..23).
 */
#define XOVER_BAND_BASE 20

/**
 * Maximum preset slots.
 */
#define MAX_PRESETS 10

/**
 * Channel / preset name buffer size.
 */
#define CHANNEL_NAME_LEN 32

/**
 * Physical output pin slots (4 S/PDIF + 1 PDM on RP2350).
 */
#define MAX_PHYSICAL_OUTPUTS 5

/**
 * Master volume mute sentinel (true −∞).
 */
#define MASTER_VOL_MUTE_DB -128.0

/**
 * The smallest buffer `dspi_link_connect`, `dspi_link_pair` and
 * `dspi_link_select_device` act on.
 */
#define LINK_REPLY_MIN 4096

/**
 * `link_devices` changed. `code` is -1, the strings are "".
 */
#define LINK_EVENT_DEVICES_CHANGED 0

/**
 * The session ended for good. `code` is the hub's WebSocket close code,
 * -1 = none; `text` the reason. A lost connection is not an end.
 */
#define LINK_EVENT_CLOSED 1

/**
 * `dspi_link_status`'s phase changed, or a reconnect try failed. `code` is
 * -1, the strings are "".
 */
#define LINK_EVENT_STATUS_CHANGED 2

/**
 * The hub issued a token: store it now. `text` is the hub id, `token` the
 * token; `code` is -1. It comes even if `dspi_link_pair` has timed out.
 */
#define LINK_EVENT_TOKEN_ISSUED 3

/**
 * The smallest buffer `dspi_hub_start` and `dspi_hub_begin_pairing` act on.
 */
#define HUB_REPLY_MIN 4096

/**
 * A new client pairs with a PIN, then presents a token. The default to offer.
 */
#define HUB_ACCESS_PIN 0

/**
 * Every connection is an admin. Only when the user asks for it.
 */
#define HUB_ACCESS_OPEN 1

/**
 * `dspi_hub_start` option: find and claim USB devices. Without it the hub serves what
 * `dspi_hub_attach_demo` gives it.
 */
#define HUB_OPT_USB 1

/**
 * `dspi_hub_start` option: an app holds or will hold devices, so nothing is scanned or
 * claimed until `dspi_hub_attach_app`. Always pass it when an app will attach.
 */
#define HUB_OPT_APP 2

/**
 * `dspi_hub_start` option: listen on loopback only. For tests.
 */
#define HUB_OPT_LOOPBACK 4

/**
 * A device came online. `code` is its handle, `text` its serial.
 */
#define HUB_EVENT_DEVICE_ONLINE 0

/**
 * A device went offline, keeping its handle for a while. `code` and `text` as above.
 */
#define HUB_EVENT_DEVICE_OFFLINE 1

/**
 * A device's handle was given up. `code` and `text` as above.
 */
#define HUB_EVENT_DEVICE_REMOVED 2

/**
 * A client's session opened, which is also how a finished pairing shows: read the
 * client list and the status again. `code` is the session, `text` "".
 */
#define HUB_EVENT_SESSION_OPENED 3

/**
 * A client's session closed. `code` is the session, `text` "".
 */
#define HUB_EVENT_SESSION_CLOSED 4

/**
 * The hub has stopped: the last event of a run. `code` is -1, `text` "".
 */
#define HUB_EVENT_STOPPED 5

/**
 * Where a fetch callback puts its answer. Valid only during the callback.
 */
typedef struct AutoEqFetchSink AutoEqFetchSink;

/**
 * A running rebuild, from [`dspi_autoeq_rebuild_start`].
 */
typedef struct AutoEqRebuildHandle AutoEqRebuildHandle;

/**
 * The handle behind the C ABI's `struct FfiCore *`: created by
 * `dspi_core_new` and freed by `dspi_core_free`.
 */
typedef struct FfiCore FfiCore;

/**
 * The handle behind the C ABI's `struct FfiHub *`: created by `dspi_hub_new` and freed
 * by `dspi_hub_free`.
 */
typedef struct FfiHub FfiHub;

/**
 * Information about a discovered DSPi device.
 */
typedef struct DeviceInfo {
  /**
   * NUL-terminated ASCII serial number.
   */
  uint8_t serial[64];
  /**
   * Bytes of `serial` before the NUL.
   */
  uint32_t serial_len;
  /**
   * Bus location id (0 where the platform has none).
   */
  uint32_t location_id;
} DeviceInfo;

/**
 * System status from the device (REQ_GET_STATUS wValue = 9).
 */
typedef struct SystemStatus {
  /**
   * Peak level per wire channel, 0.0..1.0.
   */
  float peaks[MAX_CHANNELS];
  /**
   * Core 0 load in %.
   */
  uint8_t cpu0;
  /**
   * Core 1 load in %.
   */
  uint8_t cpu1;
  /**
   * Sticky clip flags, one bit per wire channel.
   */
  uint32_t clip_flags;
  /**
   * Live active input channel count (source-aware).
   */
  uint8_t active_input_channels;
  /**
   * Wire channels (inputs + outputs).
   */
  uint8_t num_channels;
} SystemStatus;

/**
 * Parameters for a single filter band (PEQ or crossover).
 */
typedef struct FilterParams {
  /**
   * Firmware filter type (`FILTER_*`).
   */
  uint8_t filter_type;
  /**
   * User bypass: the band keeps its settings but is not processed.
   */
  bool bypass;
  /**
   * Centre or corner frequency in Hz.
   */
  float freq;
  /**
   * Quality factor (ignored by first-order types).
   */
  float q;
  /**
   * Gain in dB; for the Linkwitz Transform, the target frequency fp in Hz.
   */
  float gain;
  /**
   * Linkwitz Transform target Q (ignored by every other type).
   */
  float qp;
} FilterParams;

/**
 * UART control interface config (REQ_GET/SET_UART_CONFIG). Device-level,
 * stored in the flash directory, not in the bulk image.
 */
typedef struct UartConfig {
  /**
   * The interface is on.
   */
  bool enabled;
  /**
   * TX GPIO.
   */
  uint8_t tx_pin;
  /**
   * RX GPIO.
   */
  uint8_t rx_pin;
  /**
   * Push change notifications to the controller.
   */
  bool notify;
  /**
   * Baud rate.
   */
  uint32_t baud;
} UartConfig;

/**
 * I2C target control interface config (REQ_GET/SET_I2C_CONFIG).
 */
typedef struct I2cConfig {
  /**
   * The interface is on.
   */
  bool enabled;
  /**
   * SDA GPIO.
   */
  uint8_t sda_pin;
  /**
   * SCL GPIO.
   */
  uint8_t scl_pin;
  /**
   * 7-bit target address, 0x08..0x77.
   */
  uint8_t address;
} I2cConfig;

/**
 * Control interface outcome and run state (REQ_GET_CTRL_IFACE_STATUS).
 * `*_last_status`: 0 OK, 1 invalid pin, 2 pin in use, 5 invalid parameter.
 */
typedef struct CtrlIfaceStatus {
  /**
   * Outcome of the last UART configuration.
   */
  uint8_t uart_last_status;
  /**
   * The UART interface is running.
   */
  bool uart_live;
  /**
   * Outcome of the last I2C configuration.
   */
  uint8_t i2c_last_status;
  /**
   * The I2C interface is running.
   */
  bool i2c_live;
  /**
   * Control protocol version the firmware speaks.
   */
  uint8_t protocol_version;
} CtrlIfaceStatus;

/**
 * Complete DSP parameter state for the connected device.
 * Owned by the core handle; the GUI reads it through `dspi_get_state`.
 */
typedef struct DspState {
  /**
   * 0 = RP2040, 1 = RP2350.
   */
  uint8_t platform_id;
  /**
   * Wire channels (inputs + outputs).
   */
  uint8_t num_channels;
  /**
   * Input channels.
   */
  uint8_t num_input_channels;
  /**
   * Output channels.
   */
  uint8_t num_output_channels;
  /**
   * Wire format version of the bulk image.
   */
  uint8_t format_version;
  /**
   * Firmware major version.
   */
  uint8_t fw_major;
  /**
   * Firmware minor version.
   */
  uint8_t fw_minor;
  /**
   * Firmware patch version.
   */
  uint8_t fw_patch;
  /**
   * Firmware beta number, 0 = final.
   */
  uint8_t fw_beta;
  /**
   * `COMPAT_*`.
   */
  uint8_t compat;
  /**
   * Legacy global preamp (mirrors input 0's preamp on current firmware).
   */
  float preamp_db;
  /**
   * Global DSP bypass.
   */
  bool bypass;
  /**
   * Preamp per input, dB.
   */
  float input_preamp_db[MAX_INPUTS];
  /**
   * Device master volume: −128 = mute sentinel, −127..0 dB.
   */
  float master_volume_db;
  /**
   * 0 = independent of presets, 1 = saved with presets.
   */
  uint8_t master_volume_mode;
  /**
   * User volume, dB.
   */
  float user_volume_db;
  /**
   * User mute.
   */
  bool user_mute;
  /**
   * Loudness compensation on.
   */
  bool loudness_enabled;
  /**
   * Reference level, dB SPL.
   */
  float loudness_ref_spl;
  /**
   * Intensity, %.
   */
  float loudness_intensity;
  /**
   * Bit k: loudness processes output k.
   */
  uint16_t loudness_output_mask;
  /**
   * Crossfeed on.
   */
  bool crossfeed_enabled;
  /**
   * Crossfeed preset id.
   */
  uint8_t crossfeed_preset;
  /**
   * Custom cutoff, Hz.
   */
  float crossfeed_freq;
  /**
   * Custom feed level, dB.
   */
  float crossfeed_feed;
  /**
   * Interaural time delay on.
   */
  bool crossfeed_itd;
  /**
   * Bit p: crossfeed runs on output pair p.
   */
  uint8_t crossfeed_output_pair_mask;
  /**
   * Delay per wire channel, ms.
   */
  float channel_delays[MAX_CHANNELS];
  /**
   * Crosspoint on.
   */
  bool matrix_routing[MAX_INPUTS][MAX_OUTPUTS];
  /**
   * Crosspoint gain, dB.
   */
  float matrix_gain[MAX_INPUTS][MAX_OUTPUTS];
  /**
   * Crosspoint polarity inverted.
   */
  bool matrix_invert[MAX_INPUTS][MAX_OUTPUTS];
  /**
   * Output enabled.
   */
  bool output_enabled[MAX_OUTPUTS];
  /**
   * Output muted.
   */
  bool output_muted[MAX_OUTPUTS];
  /**
   * Output gain, dB.
   */
  float output_gain_db[MAX_OUTPUTS];
  /**
   * Output delay, ms.
   */
  float output_delay_ms[MAX_OUTPUTS];
  /**
   * Limiter on.
   */
  bool limiter_enabled[MAX_OUTPUTS];
  /**
   * 0 = unlinked, 1..4 = link group.
   */
  uint8_t limiter_link_group[MAX_OUTPUTS];
  /**
   * Threshold, dBFS.
   */
  float limiter_threshold_db[MAX_OUTPUTS];
  /**
   * Release time, ms.
   */
  float limiter_release_ms[MAX_OUTPUTS];
  /**
   * Physical output slots in use.
   */
  uint8_t num_pin_outputs;
  /**
   * GPIO per physical output slot.
   */
  uint8_t output_pins[MAX_PHYSICAL_OUTPUTS];
  /**
   * 0 = output config stored independently, 1 = saved with presets.
   */
  uint8_t output_config_mode;
  /**
   * PEQ bands [wire channel][band].
   */
  struct FilterParams filters[MAX_CHANNELS][BANDS_PER_CHANNEL];
  /**
   * Crossover bands; input rows are unused (crossovers are output-only).
   */
  struct FilterParams xover[MAX_CHANNELS][MAX_XOVER_BANDS];
  /**
   * NUL-padded UTF-8 name per wire channel.
   */
  uint8_t channel_names[MAX_CHANNELS][CHANNEL_NAME_LEN];
  /**
   * Leveller on.
   */
  bool leveller_enabled;
  /**
   * 0 = slow, 1 = medium, 2 = fast.
   */
  uint8_t leveller_speed;
  /**
   * Lookahead on.
   */
  bool leveller_lookahead;
  /**
   * Amount, %.
   */
  float leveller_amount;
  /**
   * Maximum gain, dB.
   */
  float leveller_max_gain_db;
  /**
   * Gate threshold, dBFS.
   */
  float leveller_gate_db;
  /**
   * Bit k: input k feeds the detector.
   */
  uint8_t leveller_detector_mask;
  /**
   * Bit k: gain applied to input k.
   */
  uint8_t leveller_apply_mask;
  /**
   * 0 = USB, 1 = S/PDIF, 2 = I2S, ...
   */
  uint8_t input_source;
  /**
   * LG Sound Sync decoding on.
   */
  bool lg_sound_sync_enabled;
  /**
   * Bit k: S/PDIF input k+1 is enabled (input 1 is always on).
   */
  uint8_t spdif_inputs_enabled;
  /**
   * ADAT input on.
   */
  bool adat_input_enabled;
  /**
   * RX pin of each S/PDIF input (1-4).
   */
  uint8_t spdif_rx_pins[4];
  /**
   * Data pin of each I2S input pair; active pairs = channels / 2.
   */
  uint8_t i2s_rx_pins[4];
  /**
   * I2S input channels.
   */
  uint8_t i2s_input_channels;
  /**
   * Master-mode rate shared by I2S and ADAT: 0 = 44.1k, 1 = 48k, 2 = 96k.
   */
  uint8_t i2s_input_rate;
  /**
   * 0 = master (DSPi drives BCK/LRCLK), 1 = slave.
   */
  uint8_t i2s_clock_mode;
  /**
   * ADAT input data pin, 0xFF = not set (it ships unset).
   */
  uint8_t adat_input_pin;
  /**
   * ADAT input clock: 0 = master, 1 = slave.
   */
  uint8_t adat_input_clock_mode;
  /**
   * Psychoacoustic bass on.
   */
  bool psybass_enabled;
  /**
   * Bit k: psybass processes output k.
   */
  uint16_t psybass_output_mask;
  /**
   * Cutoff, Hz.
   */
  float psybass_cutoff_hz;
  /**
   * Harmonics level, dB.
   */
  float psybass_harmonics_db;
  /**
   * Drive, dB.
   */
  float psybass_drive_db;
  /**
   * Character, %.
   */
  float psybass_character_pct;
  /**
   * Original signal level, dB.
   */
  float psybass_original_db;
  /**
   * By `UPMIX_PARAM_*` id; enable and modes as whole numbers.
   */
  float upmix[UPMIX_PARAM_COUNT];
  /**
   * By `SUBHARM_PARAM_*` id; flags, mask and mode as whole numbers.
   */
  float subharm[SUBHARM_PARAM_COUNT];
  /**
   * Program muted on the masked outputs. Runtime only: not in the bulk
   * image, never saved.
   */
  bool subharm_solo;
  /**
   * By `TUBE_PARAM_*` index; flags, mask and enums as whole numbers.
   */
  float tube[TUBE_PARAM_COUNT];
  /**
   * Per S/PDIF-or-I2S slot: 0 = S/PDIF, 1 = I2S.
   */
  uint8_t output_types[4];
  /**
   * I2S bit clock (LRCLK is the next GPIO).
   */
  uint8_t i2s_bck_pin;
  /**
   * I2S bit clock of the slave pair in split mode.
   */
  uint8_t i2s_bck_pin_slave;
  /**
   * 0 = master and slave share the clock pins, 1 = separate pins.
   */
  uint8_t i2s_clock_pin_mode;
  /**
   * MCK output on.
   */
  bool mck_enabled;
  /**
   * MCK GPIO.
   */
  uint8_t mck_pin;
  /**
   * 0 = 128 x fs, 1 = 256 x fs.
   */
  uint8_t mck_multiplier;
  /**
   * ADAT optical output (RP2350).
   */
  bool adat_out_enabled;
  /**
   * ADAT output GPIO.
   */
  uint8_t adat_out_pin;
  /**
   * The firmware has the DAC mute feature.
   */
  bool dac_mute_supported;
  /**
   * DAC mute on.
   */
  bool dac_mute_enabled;
  /**
   * The mute line is active low.
   */
  bool dac_mute_active_low;
  /**
   * GPIO, 0xFF = none.
   */
  uint8_t dac_mute_pin;
  /**
   * Hold time, ms.
   */
  uint16_t dac_mute_hold_ms;
  /**
   * Release time, ms.
   */
  uint16_t dac_mute_release_ms;
  /**
   * The firmware has the control interfaces.
   */
  bool ctrl_iface_supported;
  /**
   * UART interface config.
   */
  struct UartConfig uart;
  /**
   * I2C interface config.
   */
  struct I2cConfig i2c;
  /**
   * Control interface status.
   */
  struct CtrlIfaceStatus ctrl_status;
  /**
   * What core 1 runs (firmware `Core1Mode`).
   */
  uint8_t core1_mode;
  /**
   * Bitmask of occupied preset slots.
   */
  uint16_t preset_occupied;
  /**
   * NUL-padded UTF-8 name per preset slot.
   */
  uint8_t preset_names[MAX_PRESETS][CHANNEL_NAME_LEN];
  /**
   * Active preset slot.
   */
  uint8_t active_preset_slot;
  /**
   * 0 = load the default slot at startup, 1 = the last active one.
   */
  uint8_t preset_startup_mode;
  /**
   * Slot loaded at startup in mode 0.
   */
  uint8_t preset_default_slot;
  /**
   * True once a bulk image has been read from the device.
   */
  bool bulk_valid;
  /**
   * The last bulk image read, kept so unmodeled sections round-trip.
   */
  uint8_t bulk_raw[BULK_PARAMS_SIZE];
} DspState;

/**
 * Live upmixer state (REQ_UPMIX_GET_STATUS).
 */
typedef struct UpmixStatus {
  /**
   * True while the upmixer is processing audio.
   */
  bool active;
  /**
   * Why it is idle: 0 active, 1 disabled, 2 input not stereo, 3 rate above 48 kHz.
   */
  uint8_t parked_reason;
  /**
   * Running L/R correlation, -1..1 (0 with a passive centre).
   */
  float correlation;
  /**
   * Running L/R balance, -1..1.
   */
  float balance;
  /**
   * Current gains of the derived channels, 0..1.
   */
  float center_gain;
  /**
   * Left surround gain, 0..1.
   */
  float ls_gain;
  /**
   * Right surround gain, 0..1.
   */
  float rs_gain;
} UpmixStatus;

/**
 * Preset directory (REQ_PRESET_GET_DIR, 7-byte reply).
 */
typedef struct PresetDirectory {
  /**
   * Bitmask of occupied preset slots (10 slots).
   */
  uint16_t occupied_mask;
  /**
   * 0 = load the specified default slot, 1 = load the last active slot.
   */
  uint8_t startup_mode;
  /**
   * Slot loaded at startup in mode 0.
   */
  uint8_t default_slot;
  /**
   * Last slot loaded or saved.
   */
  uint8_t last_active;
  /**
   * 0 = output config is stored independently, 1 = it travels with presets.
   */
  uint8_t output_config_mode;
  /**
   * 0 = master volume is stored independently, 1 = it travels with presets.
   */
  uint8_t master_volume_mode;
} PresetDirectory;

/**
 * External-clock lock of the I2S input in slave mode, or of the ADAT input.
 * state: I2S 0 inactive, 1 acquiring, 2 relocking, 3 locked;
 *        ADAT 0 inactive, 1 acquiring, 2 syncing, 3 locked, 4 relocking.
 */
typedef struct InputLockStatus {
  /**
   * Lock state (see the struct docs).
   */
  uint8_t state;
  /**
   * 0 = master (DSPi drives the clock), 1 = slave.
   */
  uint8_t clock_mode;
  /**
   * Rate locked to (Hz, 0 until locked).
   */
  uint32_t detected_rate;
  /**
   * Raw measured rate in Hz.
   */
  uint32_t measured_hz;
  /**
   * ADAT: the rate is supported (44.1/48 kHz).
   */
  bool rate_ok;
  /**
   * Locks since the input started (saturates at 255).
   */
  uint8_t lock_count;
  /**
   * Lock losses since the input started (saturates at 255).
   */
  uint8_t loss_count;
} InputLockStatus;

/**
 * ADAT bulk output state (REQ_GET_ADAT_STATUS, RP2350).
 */
typedef struct AdatOutStatus {
  /**
   * The output is configured on.
   */
  bool enabled;
  /**
   * Streaming now (suspended above 48 kHz).
   */
  bool active;
  /**
   * Output GPIO.
   */
  uint8_t pin;
  /**
   * The current rate is one ADAT carries.
   */
  bool rate_ok;
  /**
   * Resynchronisations since start.
   */
  uint16_t resync_count;
  /**
   * Sample slips since start.
   */
  uint16_t slip_count;
} AdatOutStatus;

/**
 * LG Sound Sync live state (REQ_GET_LG_SOUND_SYNC_STATUS).
 */
typedef struct LgStatus {
  /**
   * The decoder is enabled.
   */
  bool enabled;
  /**
   * An LG TV's volume signalling is being decoded.
   */
  bool present;
  /**
   * TV volume 0..100; 0xFF until one has been decoded.
   */
  uint8_t volume;
  /**
   * The TV is muted.
   */
  bool muted;
} LgStatus;

/**
 * What a batch of notifications changed.
 */
typedef struct NotifyResult {
  /**
   * `NOTIFY_*` bits.
   */
  uint32_t flags;
  /**
   * Wire channels whose PEQ or crossover bands changed (bit per channel).
   */
  uint32_t filter_channels;
} NotifyResult;

/**
 * What the GUI wants. A zero mask releases the analyser.
 */
typedef struct RtaRequest {
  /**
   * RTA_TAP_INPUT or RTA_TAP_OUTPUT.
   */
  uint8_t tap;
  /**
   * Bit i = channel i at that tap (input index or output index).
   */
  uint16_t mask;
  /**
   * Also read the FFT bins (single-channel selections only).
   */
  bool wants_bins;
  /**
   * FFT size as a power of two.
   */
  uint8_t fft_order;
  /**
   * Averaging time, ms.
   */
  uint16_t avg_ms;
  /**
   * Peak hold decay, dB/s.
   */
  uint8_t peak_decay_db_s;
} RtaRequest;

/**
 * The device's analyser. `supported` is false until probed, and stays
 * false on firmware without one.
 */
typedef struct RtaCapsInfo {
  /**
   * The firmware has an analyser.
   */
  bool supported;
  /**
   * Input channels it can tap.
   */
  uint8_t input_channels;
  /**
   * Output channels it can tap.
   */
  uint8_t output_channels;
  /**
   * Smallest FFT order.
   */
  uint8_t order_min;
  /**
   * Largest FFT order.
   */
  uint8_t order_max;
  /**
   * Default FFT order.
   */
  uint8_t order_default;
  /**
   * Bands computed by the bass filter bank.
   */
  uint8_t bass_bands;
  /**
   * Bands in total.
   */
  uint8_t max_bands;
  /**
   * Dynamic range of the FFT bands, dB.
   */
  uint8_t dynamic_range_db;
  /**
   * Dynamic range of the bass bands, dB.
   */
  uint16_t bass_dynamic_range_db;
  /**
   * Nominal band centres in Hz (max_bands of them).
   */
  uint16_t centres[RTA_MAX_BANDS];
} RtaCapsInfo;

/**
 * One channel's band levels in dBFS. A silent channel (no audio, or not
 * published yet) reads the floor.
 */
typedef struct RtaChannelFrame {
  /**
   * Channel at the snapshot's tap.
   */
  uint8_t channel;
  /**
   * Bands carried.
   */
  uint8_t n_bands;
  /**
   * No level yet: the bands read the floor.
   */
  bool silent;
  /**
   * Averaged level per band, dBFS.
   */
  float avg_db[RTA_MAX_BANDS];
  /**
   * Peak-hold level per band, dBFS.
   */
  float peak_db[RTA_MAX_BANDS];
} RtaChannelFrame;

/**
 * The latest picture and telemetry. `version` changes only when what is
 * drawn changed; `telemetry_version` when the status line did.
 */
typedef struct RtaSnapshot {
  /**
   * Changes when what is drawn changed.
   */
  uint32_t version;
  /**
   * Changes when the telemetry changed.
   */
  uint32_t telemetry_version;
  /**
   * RTA_TAP_INPUT or RTA_TAP_OUTPUT.
   */
  uint8_t tap;
  /**
   * Valid entries of `frames`.
   */
  uint8_t count;
  /**
   * Analysed channels, packed in ascending channel order.
   */
  struct RtaChannelFrame frames[RTA_MAX_CHANNELS];
  /**
   * Bands with a level at this rate and transform size (bit per band).
   */
  uint64_t populated;
  /**
   * Averaged and 1/6-octave smoothed bins in dBFS; bin k at
   * k * bins_sample_rate / (2 * bins_count). 0 = none.
   */
  uint16_t bins_count;
  /**
   * Channel the bins belong to.
   */
  uint8_t bins_channel;
  /**
   * Sample rate of the bins, Hz.
   */
  uint32_t bins_sample_rate;
  /**
   * The bins, dBFS (first `bins_count` valid).
   */
  float bins_db[RTA_MAX_BINS];
  /**
   * The analyser is running.
   */
  bool running;
  /**
   * Channels being analysed.
   */
  uint8_t live_count;
  /**
   * Mask of the channels being analysed.
   */
  uint16_t live_mask;
  /**
   * Frames per second.
   */
  uint16_t frames_per_s;
  /**
   * FFT CPU time, µs per second.
   */
  uint16_t busy_us_per_s;
  /**
   * CPU time of the last frame, µs.
   */
  uint16_t last_frame_us;
  /**
   * Bass bank CPU time, µs per second.
   */
  uint16_t bass_busy_us_per_s;
  /**
   * Sample rate, Hz.
   */
  uint32_t sample_rate;
  /**
   * Lowest band carrying a level, 0xFF = none.
   */
  uint8_t first_band;
  /**
   * FFT order in use.
   */
  uint8_t fft_order;
  /**
   * The device would not take the requested configuration.
   */
  bool config_rejected;
  /**
   * How often each channel gets a new frame, in seconds.
   */
  float refresh_interval_s;
} RtaSnapshot;

/**
 * Who chose the analyser configuration the device holds.
 */
typedef struct RtaOwnership {
  /**
   * False: this console drives, and the rest is 0. True: it follows
   * someone else's configuration.
   */
  bool following;
  /**
   * The session that pushed it; 0 when the writer is unknown.
   */
  uint16_t origin;
  /**
   * The device's tap: RTA_TAP_INPUT or RTA_TAP_OUTPUT.
   */
  uint8_t tap;
  /**
   * The device's channels.
   */
  uint16_t mask;
  /**
   * The device's FFT size as a power of two.
   */
  uint8_t fft_order;
} RtaOwnership;

/**
 * One parameter of a signal type.
 */
typedef struct SiggenParam {
  /**
   * 0 unused, 1 Hz, 2 ms, 3 cycles, 4 count, 5 ratio, 6 pattern.
   */
  uint8_t semantic;
  /**
   * Smallest value.
   */
  float min;
  /**
   * Largest value.
   */
  float max;
  /**
   * Default value.
   */
  float def;
} SiggenParam;

/**
 * One signal type the generator offers.
 */
typedef struct SiggenTypeInfo {
  /**
   * Signal type id.
   */
  uint8_t id;
  /**
   * Short firmware name, NUL-terminated.
   */
  uint8_t name[9];
  /**
   * 0 continuous, 1 sweep, 2 pattern.
   */
  uint8_t timing;
  /**
   * The type's parameters (`p` of [`SiggenConfig`]).
   */
  struct SiggenParam params[4];
} SiggenTypeInfo;

/**
 * The generator on this device. `supported` false without one.
 */
typedef struct SiggenCaps {
  /**
   * The firmware has a generator.
   */
  bool supported;
  /**
   * Valid entries of `types`.
   */
  uint8_t type_count;
  /**
   * Outputs it can drive.
   */
  uint8_t output_channels;
  /**
   * Most tones of a multitone signal.
   */
  uint8_t multitone_max;
  /**
   * Bit t: type id t is valid.
   */
  uint16_t valid_mask;
  /**
   * The signal types.
   */
  struct SiggenTypeInfo types[SIGGEN_TYPE_COUNT];
} SiggenCaps;

/**
 * One signal's settings. `p` holds the type's parameters (see the caps).
 */
typedef struct SiggenConfig {
  /**
   * Signal type id.
   */
  uint8_t signal_type;
  /**
   * Bit i = output i.
   */
  uint16_t channel_mask;
  /**
   * Polarity-inverted subset of channel_mask.
   */
  uint16_t invert_mask;
  /**
   * SIGGEN_FLAG_*.
   */
  uint8_t flags;
  /**
   * Peak level, dBFS (-120..0).
   */
  float level_db;
  /**
   * Continuous: play time (0 = forever), or per-output dwell when walking;
   * sweep: one sweep. Unused by patterns.
   */
  uint32_t duration_ms;
  /**
   * Sweeps, pattern periods or walk passes (0 = forever).
   */
  uint16_t repeat;
  /**
   * Gap between repeats, ms.
   */
  uint16_t gap_ms;
  /**
   * Type-specific parameters.
   */
  float p[4];
} SiggenConfig;

/**
 * What the generator is doing.
 */
typedef struct SiggenStatus {
  /**
   * 0 idle, 1 fading in, 2 running, 3 gap, 4 fading out.
   */
  uint8_t state;
  /**
   * Signal type id.
   */
  uint8_t signal_type;
  /**
   * Output being played when walking, else 0xFF.
   */
  uint8_t active_channel;
  /**
   * Time since start, ms.
   */
  uint32_t elapsed_ms;
  /**
   * Completed repeats.
   */
  uint16_t cycles_done;
  /**
   * Of the last stop: 0 none, 1 host, 2 completed, 3 preset load, 4 reconfigured.
   */
  uint8_t stop_reason;
  /**
   * Sweep frequency now, else 0.
   */
  float current_freq;
} SiggenStatus;

/**
 * One S/PDIF output's buffer pipeline.
 */
typedef struct SpdifBufferStats {
  /**
   * Free buffers.
   */
  uint8_t free;
  /**
   * Buffers prepared.
   */
  uint8_t prepared;
  /**
   * Buffers playing.
   */
  uint8_t playing;
  /**
   * Consumer pipeline fill now, in %.
   */
  uint8_t fill_pct;
  /**
   * Lowest fill since the watermarks were reset, %.
   */
  uint8_t min_pct;
  /**
   * Highest fill since the watermarks were reset, %.
   */
  uint8_t max_pct;
} SpdifBufferStats;

/**
 * The PDM output's DMA and ring buffers, fill now / lowest / highest in %.
 */
typedef struct PdmBufferStats {
  /**
   * DMA fill now, %.
   */
  uint8_t dma_fill_pct;
  /**
   * DMA lowest fill, %.
   */
  uint8_t dma_min_pct;
  /**
   * DMA highest fill, %.
   */
  uint8_t dma_max_pct;
  /**
   * Ring fill now, %.
   */
  uint8_t ring_fill_pct;
  /**
   * Ring lowest fill, %.
   */
  uint8_t ring_min_pct;
  /**
   * Ring highest fill, %.
   */
  uint8_t ring_max_pct;
} PdmBufferStats;

/**
 * REQ_GET_BUFFER_STATS (44 bytes).
 */
typedef struct BufferStats {
  /**
   * Valid entries of `spdif`.
   */
  uint8_t num_spdif;
  /**
   * The PDM output is active.
   */
  bool pdm_active;
  /**
   * USB audio is streaming.
   */
  bool streaming;
  /**
   * Increments with each snapshot.
   */
  uint16_t sequence;
  /**
   * Per S/PDIF output.
   */
  struct SpdifBufferStats spdif[4];
  /**
   * The PDM output.
   */
  struct PdmBufferStats pdm;
} BufferStats;

/**
 * REQ_GET_SPDIF_RX_STATUS (16 bytes).
 */
typedef struct SpdifRxStatus {
  /**
   * 0 inactive, 1 acquiring, 2 locked, 3 relocking.
   */
  uint8_t state;
  /**
   * InputSource: 0 USB, 1 S/PDIF, 2 I2S, 3 ADAT, 4-6 S/PDIF 2-4.
   */
  uint8_t input_source;
  /**
   * Locks since start.
   */
  uint8_t lock_count;
  /**
   * Lock losses since start.
   */
  uint8_t loss_count;
  /**
   * Hz when locked (else the receiver's raw estimate or 0).
   */
  uint32_t sample_rate;
  /**
   * Parity errors since start.
   */
  uint32_t parity_errors;
  /**
   * Receive FIFO fill, %.
   */
  uint16_t fifo_fill_pct;
  /**
   * Receiver library debug: 0 no signal, 1 waiting stable, 2 stable.
   */
  uint8_t lib_state;
  /**
   * Stable callbacks of the receiver library (4 bits).
   */
  uint8_t stable_callbacks;
  /**
   * Lost callbacks of the receiver library (4 bits).
   */
  uint8_t lost_callbacks;
} SpdifRxStatus;

/**
 * The host's HTTP GET (module docs). `url` and `user_agent` are NUL-terminated
 * UTF-8 and always set; `accept` is null when no `Accept` header is wanted. All
 * three are valid only during the call. Send `User-Agent` as given: GitHub refuses
 * a request without one, and QNetworkAccessManager adds none.
 */
typedef void (*AutoEqFetchCallback)(void *user_data,
                                    const char *url,
                                    const char *accept,
                                    const char *user_agent,
                                    struct AutoEqFetchSink *sink);

/**
 * Platform and firmware identification (REQ_GET_PLATFORM, 7-byte reply).
 */
typedef struct PlatformInfo {
  /**
   * 0 = RP2040, 1 = RP2350.
   */
  uint8_t platform_id;
  /**
   * Output channels of this build.
   */
  uint8_t num_output_channels;
  /**
   * Firmware major version.
   */
  uint8_t fw_major;
  /**
   * Firmware minor version.
   */
  uint8_t fw_minor;
  /**
   * Firmware patch version.
   */
  uint8_t fw_patch;
  /**
   * Pre-release ordinal: 0 = final release, N = beta N.
   */
  uint8_t fw_beta;
} PlatformInfo;

/**
 * Hot-plug event callback: `event` 0 = arrived, 1 = departed; `serial` is
 * the NUL-terminated ASCII device serial, valid during the call only.
 */
typedef void (*DeviceEventCallback)(uint8_t event, const char *serial, void *user_data);

/**
 * Called from the notification thread when packets are waiting. It must
 * only schedule `dspi_process_notifications` on the GUI thread.
 */
typedef void (*NotifyCallback)(void *user_data);

/**
 * A Link session event: `event` is a `LINK_EVENT_*`. `text` and `token` are
 * never null, and are valid during the call only.
 *
 * Called on a core thread, with no core lock held. It may call
 * `dspi_link_close` and `dspi_link_status`; anything that blocks belongs on
 * the app's own thread: post it there and return.
 */
typedef void (*LinkEventCallback)(uint8_t event,
                                  int32_t code,
                                  const char *text,
                                  const char *token,
                                  void *user_data);

/**
 * A hub event: `event` is a `HUB_EVENT_*`. `text` is never null, and is valid during
 * the call only.
 *
 * Called on the hub's event thread, one at a time, with no hub lock held. It may read:
 * `dspi_hub_status`, `dspi_hub_devices`, `dspi_hub_clients`. Anything else on the hub is
 * refused from here (`false`, -1 or code `in_callback`), since it would block or wait for
 * this very thread: post it to the app's own thread and return. Blocking here holds up
 * every later event, and `dspi_hub_stop`.
 */
typedef void (*HubEventCallback)(uint8_t event, int32_t code, const char *text, void *user_data);

/**
 * Create a core instance. Free it with `dspi_core_free`. Null if creating it
 * panicked.
 */
struct FfiCore *dspi_core_new(void);

/**
 * Destroy a core instance, closing its device. Null is ignored. The handle and
 * any pointer `dspi_get_state` returned for it are invalid afterwards.
 *
 * The hotplug, notify, RTA and Link callbacks are cleared first, waiting for a call
 * in progress on another thread: once this starts closing the device, none of
 * them runs again, so `user_data` may go right after it returns. Do not call
 * this from inside one of those callbacks: it would wait for itself.
 */
void dspi_core_free(struct FfiCore *core);

/**
 * Scan for DSPis. Writes up to `max_devices` entries to `out_devices` (which
 * may be null) and returns how many were found, at most `max_devices`.
 */
uint32_t dspi_scan_devices(struct FfiCore *core,
                           struct DeviceInfo *out_devices,
                           uint32_t max_devices);

/**
 * The highest preamp (dB) the connected chip applies correctly: +18 on RP2040,
 * +24 on RP2350. The lowest is -60. 0 for a null handle.
 */
float dspi_preamp_max_db(struct FfiCore *core);

/**
 * DSPis the last scan or hot-plug poll saw on the bus but could not open (the
 * udev rule is missing, say).
 */
uint32_t dspi_inaccessible_devices(struct FfiCore *core);

/**
 * Select and open a device by serial number. False for a null or non-UTF-8
 * serial or on any error.
 */
bool dspi_select_device(struct FfiCore *core, const char *serial);

/**
 * Close the open device. It stays selected, so a replug reconnects.
 */
void dspi_disconnect(struct FfiCore *core);

/**
 * Whether a device is open.
 */
bool dspi_is_connected(const struct FfiCore *core);

/**
 * Identify the firmware and read all parameters. False only when the device
 * could not be talked to; check `DspState.compat` for compatibility.
 */
bool dspi_fetch_all(struct FfiCore *core);

/**
 * Re-read the bulk parameter image only. False on any error.
 */
bool dspi_refresh_params(struct FfiCore *core);

/**
 * Write the whole cached state to the device in one bulk transfer. False on
 * any error.
 */
bool dspi_apply_all_params(struct FfiCore *core);

/**
 * Fetch the device status into `out_status`, which may be null. False on any
 * error.
 */
bool dspi_fetch_status(struct FfiCore *core, struct SystemStatus *out_status);

/**
 * Pointer to the state, refreshed by this call; null for a null handle.
 *
 * The record belongs to the handle and its address never changes until
 * `dspi_core_free`, so a caller may keep the pointer; what it reads is the
 * state as of the last `dspi_get_state`. This call rewrites the record: every
 * reader must be on the thread that calls it (the Qt app's GUI thread), or
 * must serialise reads and calls itself.
 */
const struct DspState *dspi_get_state(const struct FfiCore *core);

/**
 * Longest channel or output delay the connected platform supports, ms. 0 for a
 * null handle.
 */
float dspi_max_delay_ms(const struct FfiCore *core);

/**
 * Clear the device's sticky clip flags. False on any error.
 */
bool dspi_clear_clips(struct FfiCore *core);

/**
 * Set PEQ band `band` (0..9) of wire channel `ch`. False on any error.
 */
bool dspi_set_filter(struct FfiCore *core, uint8_t ch, uint8_t band, struct FilterParams params);

/**
 * Set crossover band `xband` (0..3) of an output's wire channel `ch`. False
 * on any error.
 */
bool dspi_set_crossover(struct FfiCore *core,
                        uint8_t ch,
                        uint8_t xband,
                        struct FilterParams params);

/**
 * Bypass one band. `band` is a PEQ band (0..9) or a crossover band (20..23).
 * False on any error.
 */
bool dspi_set_band_bypass(struct FfiCore *core, uint8_t ch, uint8_t band, bool bypass);

/**
 * Legacy preamp: every input to the same value, dB. False on any error.
 */
bool dspi_set_preamp(struct FfiCore *core, float db);

/**
 * Preamp of one input (input index), dB. False on any error.
 */
bool dspi_set_input_preamp(struct FfiCore *core, uint8_t input, float db);

/**
 * Global DSP bypass. False on any error.
 */
bool dspi_set_bypass(struct FfiCore *core, bool enabled);

/**
 * Master volume in dB (-128 = mute, otherwise -127..0). False on any error.
 */
bool dspi_set_master_volume(struct FfiCore *core, float db);

/**
 * 0 = master volume independent of presets, 1 = saved with presets. False on
 * any error.
 */
bool dspi_set_master_volume_mode(struct FfiCore *core, uint8_t mode);

/**
 * Persist the live master volume (independent mode). A `PRESET_*` status,
 * 0xFF on any other error.
 */
uint8_t dspi_save_master_volume(struct FfiCore *core);

/**
 * User volume, dB (-60..0). False on any error.
 */
bool dspi_set_user_volume(struct FfiCore *core, float db);

/**
 * User mute. False on any error.
 */
bool dspi_set_user_mute(struct FfiCore *core, bool muted);

/**
 * Delay of wire channel `ch`, ms (an output channel's delay is its output
 * delay). False on any error.
 */
bool dspi_set_delay(struct FfiCore *core, uint8_t ch, float ms);

/**
 * Loudness compensation on or off. False on any error.
 */
bool dspi_set_loudness(struct FfiCore *core, bool enabled);

/**
 * Loudness reference level, dB SPL. False on any error.
 */
bool dspi_set_loudness_ref(struct FfiCore *core, float spl);

/**
 * Loudness intensity, percent. False on any error.
 */
bool dspi_set_loudness_intensity(struct FfiCore *core, float pct);

/**
 * Bit k: loudness compensates output k. False on any error.
 */
bool dspi_set_loudness_mask(struct FfiCore *core, uint16_t mask);

/**
 * Crossfeed on or off. False on any error.
 */
bool dspi_set_crossfeed(struct FfiCore *core, bool enabled);

/**
 * Crossfeed preset. False on any error.
 */
bool dspi_set_crossfeed_preset(struct FfiCore *core, uint8_t preset);

/**
 * Custom crossfeed frequency, Hz. False on any error.
 */
bool dspi_set_crossfeed_freq(struct FfiCore *core, float freq);

/**
 * Custom crossfeed level, dB. False on any error.
 */
bool dspi_set_crossfeed_feed(struct FfiCore *core, float feed);

/**
 * Crossfeed interaural time difference on or off. False on any error.
 */
bool dspi_set_crossfeed_itd(struct FfiCore *core, bool enabled);

/**
 * Bit p: crossfeed runs on output pair p. False on any error.
 */
bool dspi_set_crossfeed_outputs(struct FfiCore *core, uint8_t pair_mask);

/**
 * Leveller on or off. False on any error.
 */
bool dspi_set_leveller_enabled(struct FfiCore *core, bool enabled);

/**
 * Leveller amount, percent. False on any error.
 */
bool dspi_set_leveller_amount(struct FfiCore *core, float pct);

/**
 * 0 = slow, 1 = medium, 2 = fast. False on any error.
 */
bool dspi_set_leveller_speed(struct FfiCore *core, uint8_t speed);

/**
 * Leveller maximum gain, dB. False on any error.
 */
bool dspi_set_leveller_max_gain(struct FfiCore *core, float db);

/**
 * Leveller look-ahead on or off. False on any error.
 */
bool dspi_set_leveller_lookahead(struct FfiCore *core, bool enabled);

/**
 * Leveller gate, dB. False on any error.
 */
bool dspi_set_leveller_gate(struct FfiCore *core, float db);

/**
 * Bit k of each mask = input k. False on any error.
 */
bool dspi_set_leveller_masks(struct FfiCore *core, uint8_t detector, uint8_t apply);

/**
 * Select the audio input source (firmware `InputSource` enum). False on any
 * error.
 */
bool dspi_set_input_source(struct FfiCore *core, uint8_t source);

/**
 * Set psybass parameter `param` (`PSYBASS_PARAM_*`). False on any error.
 */
bool dspi_set_psybass_param(struct FfiCore *core, uint8_t param, float value);

/**
 * Bit k: psybass processes output k. False on any error.
 */
bool dspi_set_psybass_mask(struct FfiCore *core, uint16_t mask);

/**
 * Psybass on or off. False on any error.
 */
bool dspi_set_psybass_enabled(struct FfiCore *core, bool enabled);

/**
 * One matrix crosspoint: `input` to `output`, gain in dB. False on any error.
 */
bool dspi_set_matrix_route(struct FfiCore *core,
                           uint8_t input,
                           uint8_t output,
                           bool enabled,
                           float gain,
                           bool invert);

/**
 * Enable or disable an output. The resulting state (1 on, 0 off; the firmware
 * may refuse a PDM / Core 1 conflict), -1 on any error.
 */
int8_t dspi_set_output_enable(struct FfiCore *core, uint8_t output, bool enabled);

/**
 * Output gain, dB. False on any error.
 */
bool dspi_set_output_gain(struct FfiCore *core, uint8_t output, float db);

/**
 * Output mute. False on any error.
 */
bool dspi_set_output_mute(struct FfiCore *core, uint8_t output, bool muted);

/**
 * Output delay, ms. False on any error.
 */
bool dspi_set_output_delay(struct FfiCore *core, uint8_t output, float ms);

/**
 * Set limiter parameter `param` (`LIMITER_PARAM_*`) of `output`
 * (`LIMITER_ALL_OUTPUTS` = every output). False on any error.
 */
bool dspi_set_limiter_param(struct FfiCore *core, uint8_t output, uint8_t param, float value);

/**
 * Read the gain reduction (dB, positive = reducing) of every output into
 * `out_gr`, which must hold `MAX_OUTPUTS` floats; outputs the device does not
 * report read 0. False for a null pointer or on any error.
 */
bool dspi_fetch_limiter_meter(struct FfiCore *core, float *out_gr);

/**
 * Set the name of wire channel `ch`. False for a null or non-UTF-8 name or on
 * any error.
 */
bool dspi_set_channel_name(struct FfiCore *core, uint8_t ch, const char *name);

/**
 * Read a channel name from the device into `out_buf` (NUL-terminated, cut to
 * `buf_len` at a character boundary). False for a null or empty buffer or on
 * any error.
 */
bool dspi_get_channel_name(struct FfiCore *core, uint8_t ch, char *out_buf, uint32_t buf_len);

/**
 * Set upmixer parameter `id` (`UPMIX_PARAM_*`). RP2350 only. False on any
 * error.
 */
bool dspi_set_upmix_param(struct FfiCore *core, uint8_t id, float value);

/**
 * Read the upmixer's status into `out`. False for a null pointer or on any
 * error.
 */
bool dspi_fetch_upmix_status(struct FfiCore *core, struct UpmixStatus *out);

/**
 * Set subharmonic synth parameter `id` (`SUBHARM_PARAM_*`). False on any
 * error.
 */
bool dspi_set_subharm_param(struct FfiCore *core, uint8_t id, float value);

/**
 * Solo the subharmonic synth. False on any error.
 */
bool dspi_set_subharm_solo(struct FfiCore *core, bool solo);

/**
 * The headroom the subharmonic settings cost, dB (0 = none), into `out_db`.
 * False for a null pointer or on any error.
 */
bool dspi_fetch_subharm_headroom(struct FfiCore *core, float *out_db);

/**
 * The synthesized sub peak per output, 0..1, into `out`, which must hold
 * `MAX_OUTPUTS` floats; outputs the device does not report read 0. False for a
 * null pointer or on any error.
 */
bool dspi_fetch_subharm_meter(struct FfiCore *core, float *out);

/**
 * Set tube parameter `idx` (`TUBE_PARAM_*`). False on any error.
 */
bool dspi_set_tube_param(struct FfiCore *core, uint8_t idx, float value);

/**
 * Save the live state to `slot`, waiting for the device to finish the deferred
 * save. A `PRESET_*` status, 0xFF on any other error.
 */
uint8_t dspi_save_preset(struct FfiCore *core, uint8_t slot);

/**
 * Load a preset and re-read every parameter. A `PRESET_*` status, 0xFF on any
 * other error.
 */
uint8_t dspi_load_preset(struct FfiCore *core, uint8_t slot);

/**
 * Copy the live state to `dest` and re-save it to `source` (which stays
 * active). The `PRESET_*` status of the first failing save, 0xFF on any other
 * error.
 */
uint8_t dspi_copy_preset(struct FfiCore *core, uint8_t source, uint8_t dest);

/**
 * Delete a preset. A `PRESET_*` status, 0xFF on any other error.
 */
uint8_t dspi_delete_preset(struct FfiCore *core, uint8_t slot);

/**
 * Rename a preset. False for a null or non-UTF-8 name or on any error.
 */
bool dspi_set_preset_name(struct FfiCore *core, uint8_t slot, const char *name);

/**
 * Read a preset's name into `out_buf` (NUL-terminated, cut to `buf_len` at a
 * character boundary). False for a null or empty buffer or on any error.
 */
bool dspi_get_preset_name(struct FfiCore *core, uint8_t slot, char *out_buf, uint32_t buf_len);

/**
 * Read the preset directory into `out_dir`. False for a null pointer or on
 * any error.
 */
bool dspi_get_preset_directory(struct FfiCore *core, struct PresetDirectory *out_dir);

/**
 * Boot preset: mode 0 = load `default_slot`, 1 = load the last active slot.
 * False on any error.
 */
bool dspi_set_preset_startup(struct FfiCore *core, uint8_t mode, uint8_t default_slot);

/**
 * Save the live state to flash. A `FLASH_*` status; `FLASH_ERR_WRITE` on any
 * other error.
 */
uint8_t dspi_save_params(struct FfiCore *core);

/**
 * Revert to saved (reloads the active preset). A `FLASH_*` status;
 * `FLASH_ERR_WRITE` on any other error.
 */
uint8_t dspi_load_params(struct FfiCore *core);

/**
 * Restore the factory defaults. A `FLASH_*` status; `FLASH_ERR_WRITE` on any
 * other error.
 */
uint8_t dspi_factory_reset(struct FfiCore *core);

/**
 * The live state now matches the active preset (after connecting, loading a
 * preset, saving to the active slot, reverting or a factory reset).
 */
void dspi_capture_baseline(struct FfiCore *core);

/**
 * Whether the live state differs from the active preset. False for a null
 * handle.
 */
bool dspi_preset_dirty(struct FfiCore *core);

/**
 * What differs from the active preset, as a JSON array of sentences, into
 * `buf`. Returns the bytes needed including the NUL; a null or too small
 * buffer is left alone, so the caller can retry. 0 for a null handle.
 */
uint32_t dspi_preset_changes(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Magnitude in dB at one frequency for a chain of bands; 0 for a null or empty
 * chain. `filters` must hold `num_filters` records.
 */
float dspi_compute_response(const struct FilterParams *filters, uint32_t num_filters, float freq);

/**
 * The 201-point magnitude curve (dB, 10 Hz..20 kHz log-spaced) into
 * `out_magnitudes`, which must hold `MAGNITUDE_POINTS` doubles. A null chain
 * is an empty one. False for a null output. `filters` must hold `num_filters`
 * records.
 */
bool dspi_compute_magnitude_curve(const struct FilterParams *filters,
                                  uint32_t num_filters,
                                  double *out_magnitudes);

/**
 * The 201-point phase curve in degrees over the same grid, continuous when
 * `unwrap` is set, otherwise wrapped to +-180, into `out_phases`, which must
 * hold `MAGNITUDE_POINTS` doubles. A null chain is an empty one. False for a
 * null output. `filters` must hold `num_filters` records.
 */
bool dspi_compute_phase_curve(const struct FilterParams *filters,
                              uint32_t num_filters,
                              bool unwrap,
                              double *out_phases);

/**
 * Returns a PIN_CONFIG_* status (0 = success), 0xFF on communication error.
 */
uint8_t dspi_set_output_pin(struct FfiCore *core, uint8_t slot, uint8_t pin);

/**
 * Returns the pin number, 0xFF on error.
 */
uint8_t dspi_fetch_output_pin(struct FfiCore *core, uint8_t slot);

/**
 * 0 = output config stored independently, 1 = saved with presets.
 */
bool dspi_set_output_config_mode(struct FfiCore *core, uint8_t mode);

/**
 * Persist the live output config (independent mode). PRESET_* code, 0xFF on error.
 */
uint8_t dspi_save_output_config(struct FfiCore *core);

/**
 * Restart the device into its USB bootloader.
 */
bool dspi_enter_bootloader(struct FfiCore *core);

/**
 * Hold the device lock across a flow of several calls, for at most
 * `timeout_ms` (capped at 60 000), until `dspi_device_lock_release`: another
 * DSPi Link session's commands answer locked meanwhile. Blocking over Link:
 * call it off the UI thread. Replies in JSON {ok} or {ok, code, error}
 * (`locked` when another session holds it) and returns the length needed. A
 * retry with a larger buffer is harmless: an acquire while held keeps the lock.
 */
uint32_t dspi_device_lock_acquire(struct FfiCore *core,
                                  const char *reason,
                                  uint32_t timeout_ms,
                                  char *buf,
                                  uint32_t len);

/**
 * Release the lock `dspi_device_lock_acquire` took, and only that one: an IR
 * learn's lock ends with its read, cancel or window, `dspi_enter_bootloader`'s
 * when the device leaves or after 60 s. Idempotent; never blocks.
 */
void dspi_device_lock_release(struct FfiCore *core);

/**
 * Core 1 mode (0 = idle, 1 = PDM, 2 = EQ worker), -1 on error.
 */
int8_t dspi_fetch_core1_mode(struct FfiCore *core);

/**
 * 1 if enabling `output` would conflict with Core 1's mode, 0 if not, -1 on error.
 */
int8_t dspi_check_core1_conflict(struct FfiCore *core, uint8_t output);

/**
 * Register a callback for device arrival/departure events; NULL clears it,
 * waiting for a call in progress on another thread. False for a null handle.
 * It runs on the thread that calls `dspi_poll_hotplug`, and must not set
 * listeners from inside the call.
 */
bool dspi_set_hotplug_callback(struct FfiCore *core,
                               void (*callback)(uint8_t event, const char *serial, void *user_data),
                               void *user_data);

/**
 * Poll for hot-plug changes (~every 500 ms). Fires the registered callback
 * for arrivals (event 0) and departures (event 1), reconnects the selected
 * device when it comes back and closes one that went away. A reconnect runs
 * here, so the call can take a few hundred milliseconds on a replug. Call
 * `dspi_scan_devices` first, or every unit present is announced as arrived.
 */
void dspi_poll_hotplug(struct FfiCore *core);

/**
 * Slot type: 0 = S/PDIF, 1 = I2S.
 */
uint8_t dspi_set_output_type(struct FfiCore *core, uint8_t slot, uint8_t kind);

/**
 * I2S BCK pin (LRCLK = +1); role 0 = master/shared, 1 = slave pair.
 */
uint8_t dspi_set_i2s_bck_pin(struct FfiCore *core, uint8_t role, uint8_t pin);

/**
 * 0 = shared clock pins, 1 = separate slave pins.
 */
uint8_t dspi_set_i2s_clock_pin_mode(struct FfiCore *core, uint8_t mode);

/**
 * Master clock output on/off.
 */
uint8_t dspi_set_mck_enabled(struct FfiCore *core, bool enabled);

/**
 * Master clock pin (MCK off first).
 */
uint8_t dspi_set_mck_pin(struct FfiCore *core, uint8_t pin);

/**
 * 0 = 128 x fs, 1 = 256 x fs.
 */
uint8_t dspi_set_mck_multiplier(struct FfiCore *core, uint8_t mult);

/**
 * ADAT optical output (RP2350).
 */
uint8_t dspi_set_adat_out_enabled(struct FfiCore *core, bool enabled);

/**
 * ADAT output data pin.
 */
uint8_t dspi_set_adat_out_pin(struct FfiCore *core, uint8_t pin);

/**
 * S/PDIF input RX pin (index 0-3).
 */
uint8_t dspi_set_spdif_rx_pin(struct FfiCore *core, uint8_t index, uint8_t pin);

/**
 * Enable S/PDIF input 2-4 (index 1-3).
 */
uint8_t dspi_set_spdif_input_enabled(struct FfiCore *core, uint8_t index, bool enabled);

/**
 * I2S input data pin of a pair (0-3).
 */
uint8_t dspi_set_i2s_rx_pin(struct FfiCore *core, uint8_t pair, uint8_t pin);

/**
 * I2S input channels: 2, 4, 6 or 8.
 */
uint8_t dspi_set_i2s_input_channels(struct FfiCore *core, uint8_t channels);

/**
 * ADAT input on/off (needs a pin).
 */
uint8_t dspi_set_adat_input_enabled(struct FfiCore *core, bool enabled);

/**
 * ADAT input data pin; 0xFF clears it.
 */
uint8_t dspi_set_adat_input_pin(struct FfiCore *core, uint8_t pin);

/**
 * ADAT input clock: 0 = master, 1 = slave.
 */
uint8_t dspi_set_adat_input_clock_mode(struct FfiCore *core, uint8_t mode);

/**
 * Master-mode input rate for I2S and ADAT: 0 = 44.1k, 1 = 48k, 2 = 96k.
 */
bool dspi_set_input_rate(struct FfiCore *core, uint8_t index);

/**
 * The rate the pipeline runs at now, Hz (0 if unknown).
 */
uint32_t dspi_fetch_input_rate(struct FfiCore *core);

/**
 * I2S input clock: 0 = master, 1 = slave (applied by the device later).
 */
bool dspi_set_i2s_clock_mode(struct FfiCore *core, uint8_t mode);

/**
 * `which`: 0 = I2S slave lock, 1 = ADAT input lock; false for another value.
 */
bool dspi_fetch_input_lock(struct FfiCore *core, uint8_t which, struct InputLockStatus *out);

/**
 * The ADAT output's status (all zero on RP2040).
 */
bool dspi_fetch_adat_out_status(struct FfiCore *core, struct AdatOutStatus *out);

/**
 * Send a DAC mute config; read it back with `dspi_fetch_dac_mute` ~150 ms later.
 */
bool dspi_set_dac_mute(struct FfiCore *core,
                       bool enabled,
                       bool active_low,
                       uint8_t pin,
                       uint16_t hold_ms,
                       uint16_t release_ms);

/**
 * Re-read the DAC mute config into the state.
 */
bool dspi_fetch_dac_mute(struct FfiCore *core);

/**
 * Pulse the DAC mute output for ~1 s. Returns 0 when started, 3 when the
 * feature is disabled, 255 if the device did not answer.
 */
uint8_t dspi_test_dac_mute(struct FfiCore *core);

/**
 * LG Sound Sync on or off.
 */
bool dspi_set_lg_sound_sync(struct FfiCore *core, bool enabled);

/**
 * LG Sound Sync's status.
 */
bool dspi_fetch_lg_status(struct FfiCore *core, struct LgStatus *out);

/**
 * Re-read both control interface configs and their status into the state.
 */
bool dspi_fetch_ctrl_ifaces(struct FfiCore *core);

/**
 * Send a UART config; read the outcome with `dspi_fetch_ctrl_ifaces` ~250 ms later.
 */
bool dspi_set_uart(struct FfiCore *core, struct UartConfig config);

/**
 * Send an I2C config; read the outcome with `dspi_fetch_ctrl_ifaces` later.
 */
bool dspi_set_i2c(struct FfiCore *core, struct I2cConfig config);

/**
 * Register the callback the notification listener thread calls when
 * packets are waiting; NULL clears it, waiting for a call in progress. It runs
 * on that thread: it must only schedule `dspi_process_notifications` on the
 * GUI thread.
 */
void dspi_set_notify_callback(struct FfiCore *core,
                              void (*callback)(void *user_data),
                              void *user_data);

/**
 * Apply the queued device notifications to the state. `out` receives what
 * changed (`NOTIFY_*` flags and the wire channels whose filters changed);
 * zeros for a null handle. `out` may be null.
 */
void dspi_process_notifications(struct FfiCore *core, struct NotifyResult *out);

/**
 * Register the callback the analyser worker calls (on its own thread) when
 * the caps or the snapshot changed. It must only schedule work on the GUI
 * thread. NULL stops the calls; once this returns, no call is in progress.
 */
void dspi_rta_set_callback(struct FfiCore *core,
                           void (*callback)(void *user_data),
                           void *user_data);

/**
 * Probe and start polling the connected device's analyser (compatible
 * firmware only). Stops by itself on disconnect.
 */
void dspi_rta_start(struct FfiCore *core);

/**
 * What to analyse. A zero mask releases the analyser.
 */
void dspi_rta_set_request(struct FfiCore *core, const struct RtaRequest *request);

/**
 * The analyser's capabilities (`supported` false until probed or without
 * one, and for a null handle).
 */
void dspi_rta_get_caps(struct FfiCore *core, struct RtaCapsInfo *out);

/**
 * Copy the latest snapshot into `out` (the empty one for a null handle).
 */
void dspi_rta_get_snapshot(struct FfiCore *core, struct RtaSnapshot *out);

/**
 * Whether this console drives the analyser or follows another one's
 * configuration (driving, all zero, for a null handle). The analyser
 * callback is called when this changes.
 */
void dspi_rta_get_ownership(struct FfiCore *core, struct RtaOwnership *out);

/**
 * Stop following and push this console's own request on the next poll.
 */
void dspi_rta_take_control(struct FfiCore *core);

/**
 * The generator's caps and signal types. False on a USB error; true with
 * `supported` false when the firmware has no generator.
 */
bool dspi_siggen_fetch_caps(struct FfiCore *core, struct SiggenCaps *out);

/**
 * The config the generator runs (as the device sanitised it).
 */
bool dspi_siggen_get_config(struct FfiCore *core, struct SiggenConfig *out);

/**
 * Stage a config; a running generator restarts with it. The device ACKs
 * even a config it refuses: read it back to check.
 */
bool dspi_siggen_set_config(struct FfiCore *core, const struct SiggenConfig *cfg);

/**
 * SIGGEN_CTL_START / STOP (fade) / STOP_NOW. False if refused.
 */
bool dspi_siggen_control(struct FfiCore *core, uint16_t action);

/**
 * The generator's state.
 */
bool dspi_siggen_get_status(struct FfiCore *core, struct SiggenStatus *out);

/**
 * One REQ_GET_STATUS u32 counter (STAT_*).
 */
bool dspi_fetch_stat(struct FfiCore *core, uint16_t which, uint32_t *out);

/**
 * The audio buffers' fill statistics.
 */
bool dspi_fetch_buffer_stats(struct FfiCore *core, struct BufferStats *out);

/**
 * Restart the buffer watermarks.
 */
bool dspi_reset_buffer_stats(struct FfiCore *core);

/**
 * The S/PDIF receiver's status.
 */
bool dspi_fetch_spdif_rx_status(struct FfiCore *core, struct SpdifRxStatus *out);

/**
 * `out` receives 24 bytes of IEC 60958 channel status.
 */
bool dspi_fetch_spdif_rx_channel_status(struct FfiCore *core, uint8_t *out);

/**
 * GPIO of S/PDIF receiver `index`; false if it has none.
 */
bool dspi_fetch_spdif_rx_pin(struct FfiCore *core, uint8_t index, uint8_t *out);

/**
 * Copy the notification log lines after `after_id` into `buf` as
 * "time_ms<TAB>text<LF>" (ms since the Unix epoch), stopping before `buf`
 * would overflow. A line too long for `buf` even on its own is dropped.
 * Returns the id of the last line written or dropped (`after_id` if none);
 * call again from there to get the rest.
 */
uint64_t dspi_monitor_read(struct FfiCore *core, uint64_t after_id, char *buf, uint32_t buf_len);

/**
 * Empty the notification log.
 */
void dspi_monitor_clear(struct FfiCore *core);

/**
 * The device's configuration as a `.dspipreset` document. `links` = the
 * app's input-pair link mask. Returns the length needed.
 *
 * With no device's state to export, the text is instead the JSON failure reply
 * `{"ok":false,"code":<kind>,"error":<sentence>}`: a document has no `ok` key.
 * Check before writing it to a file.
 */
uint32_t dspi_config_export(struct FfiCore *core,
                            const char *name,
                            const char *app_version,
                            uint8_t links,
                            char *buf,
                            uint32_t len);

/**
 * Check a document and describe it, as JSON {ok, error, name, platform,
 * firmware, savedUtc}. Returns the length needed.
 */
uint32_t dspi_config_inspect(const char *text, char *buf, uint32_t len);

/**
 * Apply a document (`options`: 1 = volumes, 2 = hardware I/O). Writes JSON
 * {ok, error, lines, clean, links (or null), hardwareWritten}. Returns the
 * length needed.
 *
 * Don't retry on a short buffer: a reply too long means the write has
 * happened, and a second call applies it again. Give it a large enough buffer
 * the first time.
 */
uint32_t dspi_config_import(struct FfiCore *core,
                            const char *text,
                            uint32_t options,
                            char *buf,
                            uint32_t len);

/**
 * Every channel's filters as a text file (`inputs` = live inputs to write),
 * or the JSON failure reply as [`dspi_config_export`] gives it: a filter file
 * starts with `#`.
 */
uint32_t dspi_filters_export(struct FfiCore *core, uint8_t inputs, char *buf, uint32_t len);

/**
 * What a filter file holds, for the channel picker (JSON).
 */
uint32_t dspi_filters_inspect(struct FfiCore *core,
                              const char *text,
                              uint8_t inputs,
                              char *buf,
                              uint32_t len);

/**
 * Apply a filter file to the channels in `wires` (wire indices). Writes
 * JSON {ok, error, lines}. Returns the length needed.
 *
 * Don't retry on a short buffer: a reply too long means the write has
 * happened, and a second call applies it again. Give it a large enough buffer
 * the first time.
 */
uint32_t dspi_filters_import(struct FfiCore *core,
                             const char *text,
                             const uint8_t *wires,
                             uint32_t count,
                             char *buf,
                             uint32_t len);

/**
 * Read the whole control surfaces configuration from the device (bindings,
 * IR commands, groups, macros, display, aux). Returns false on a transfer
 * error; firmware without control surfaces reads as unsupported.
 */
bool dspi_cs_fetch(struct FfiCore *core);

/**
 * The control surfaces configuration as JSON. Returns the length needed.
 */
uint32_t dspi_cs_snapshot(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Perform one control surfaces operation, given as JSON {op, index, ...}.
 * Writes JSON {ok, status, error, ...}. Returns the length needed.
 *
 * Don't retry on a short buffer: a reply too long means the write has
 * happened, and a second call applies it again. Give it a large enough buffer
 * the first time.
 */
uint32_t dspi_cs_apply(struct FfiCore *core, const char *op, char *buf, uint32_t len);

/**
 * GPIOs held by live control surface bindings: fills `pins` and `slots`
 * (up to `max` each) and returns how many there are.
 */
uint32_t dspi_cs_pin_uses(struct FfiCore *core, uint8_t *pins, uint8_t *slots, uint32_t max);

/**
 * Boards in BOOTSEL (Raspberry Pi's ROM loader, not DSPi) on the USB bus:
 * fills the RP2040 and RP2350 counts. Either pointer may be null.
 */
void dspi_bootloader_counts(uint32_t *rp2040, uint32_t *rp2350);

/**
 * Open the built-in demo device: a simulated RP2350 that answers reads and
 * writes and notifies. Replaces any open device. Follow it with
 * `dspi_fetch_all`, as after `dspi_select_device`.
 */
bool dspi_open_demo(struct FfiCore *core);

/**
 * What the extension channel offers, as probed on connect (no traffic):
 * JSON {ok, supported, hasPairMap, hasCoreVreg}. Returns the length needed.
 */
uint32_t dspi_ext_status(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Read the live crossfeed pair map into `out`. `out_len` must be at least 4;
 * a shorter buffer is false with no traffic. Also false on firmware without
 * the extension.
 */
bool dspi_fetch_crossfeed_pair_map(struct FfiCore *core, uint8_t *out, uint32_t out_len);

/**
 * Set the crossfeed pair map (`map_len` 4 bytes). Returns 0 on success, the
 * device's status byte if it refused, 0xFF otherwise: an invalid map (nothing
 * is sent), firmware without the extension, or no device.
 */
uint8_t dspi_set_crossfeed_pair_map(struct FfiCore *core, const uint8_t *map, uint32_t map_len);

/**
 * Whether `map` (`map_len` 4 bytes) is a pair map the firmware takes on a
 * platform with `num_pairs` stereo pairs: the rule
 * `dspi_set_crossfeed_pair_map` applies, for telling an editor as the pairs
 * are picked. No device involved. False for a null map or another length.
 */
bool dspi_crossfeed_pair_map_valid(const uint8_t *map, uint32_t map_len, uint8_t num_pairs);

/**
 * The K340's pair map (one DAC per ear) into `out`. `out_len` must be at
 * least 4; a shorter or null buffer is false.
 */
bool dspi_crossfeed_k340_pair_map(uint8_t *out, uint32_t out_len);

/**
 * The output pair mask that goes with the K340's pair map.
 */
uint8_t dspi_crossfeed_k340_pair_mask(void);

/**
 * The core voltage extension's status: JSON {ok, liveVreg, millivolts,
 * storedSel, defaultVreg, autoRaised, autoDisabled, hangCount, trialActive,
 * trialVreg, failedTrialVreg, failedTrialUptimeS, uptimeS}. Returns the
 * length needed.
 */
uint32_t dspi_fetch_core_vreg(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Core voltage write: `op` 0 set (value = VREG code, 0 = build default),
 * 1 trial, 2 end trial, 3 auto (value 0/1), 4 clear. Out-of-range requests
 * are refused here with nothing sent. A set or trial above 1.20 V and above
 * what the unit reports now needs `word`, exactly "OVERVOLT"; null or anything
 * else refuses it with nothing written. Returns 0 on success, the device's
 * status byte if it refused, 0xFF otherwise. Read the status back with
 * `dspi_fetch_core_vreg`.
 */
uint8_t dspi_core_vreg_op(struct FfiCore *core, uint8_t op, uint8_t value, const char *word);

/**
 * The user's name for input source `source` ("" when unnamed), cut to fit
 * `out_buf`; 32 bytes always fit. False on firmware without source names.
 */
bool dspi_get_input_source_name(struct FfiCore *core,
                                uint8_t source,
                                char *out_buf,
                                uint32_t buf_len);

/**
 * Name input source `source`; "" clears it. At most 31 bytes of UTF-8. False
 * for a null or invalid string (nothing is sent), and as the device refuses.
 */
bool dspi_set_input_source_name(struct FfiCore *core, uint8_t source, const char *name);

/**
 * The device's own name ("" when unnamed), cut to fit `out_buf`; 32 bytes
 * always fit. False on firmware without device names.
 */
bool dspi_get_device_name(struct FfiCore *core, char *out_buf, uint32_t buf_len);

/**
 * Rename the device; "" clears it. At most 31 bytes of UTF-8. False for a
 * null or invalid string (nothing is sent), and as the device refuses.
 */
bool dspi_set_device_name(struct FfiCore *core, const char *name);

/**
 * The name of input source `source` as last known ("" when unnamed), cut to
 * fit `out_buf`, with no traffic: for showing names, which connect has read
 * and notifications keep current. 32 bytes always fit. False on firmware
 * without source names, and for a source past the table.
 */
bool dspi_cached_input_source_name(struct FfiCore *core,
                                   uint8_t source,
                                   char *out_buf,
                                   uint32_t buf_len);

/**
 * The device's name as last known, as [`dspi_cached_input_source_name`]. False
 * on firmware without device names.
 */
bool dspi_cached_device_name(struct FfiCore *core, char *out_buf, uint32_t buf_len);

/**
 * On the demo device only: someone else renames input source `target`, or the
 * device for 0xFF. "" clears the name. False on anything else.
 */
bool dspi_demo_rename_elsewhere(struct FfiCore *core, uint8_t target, const char *name);

/**
 * On the demo device only: how an output-latency request lands. `mode` 0 at
 * once, 1 after `reads` status reads, 2 never, 3 dropped after `reads` status
 * reads; `blackout` status reads stall first while one is pending. False on
 * anything else.
 */
bool dspi_demo_latency_timing(struct FfiCore *core, uint8_t mode, uint8_t reads, uint8_t blackout);

/**
 * On the demo device only: how many output-latency requests it has received,
 * or `u32::MAX` on anything else.
 */
uint32_t dspi_demo_latency_sets(struct FfiCore *core);

/**
 * On the demo device only: how `dspi_save_output_config` answers from now on.
 * 0 goes through, 0xFF stalls, another byte is that `PRESET_*` status. False on
 * anything else.
 */
bool dspi_demo_output_save_status(struct FfiCore *core, uint8_t status);

/**
 * The demo device as firmware of wire format `wire` (17, 26, 31 or 33), for
 * read-only tests. Replaces any open device. False for any other format.
 */
bool dspi_demo_open_wire(struct FfiCore *core, uint8_t wire);

/**
 * How many writes this core has refused because the connection is read-only.
 */
uint32_t dspi_read_only_refusals(struct FfiCore *core);

/**
 * The `WIRE_FEAT_*` bits the connected firmware's wire format carries: all of
 * them on V32 and newer, none with no device or below V16.
 */
uint32_t dspi_wire_features(struct FfiCore *core);

/**
 * The output latency's status: JSON {ok, raw, fields: [{name, value}]}.
 * Returns the length needed.
 */
uint32_t dspi_fetch_output_latency(struct FfiCore *core, char *buf, uint32_t len);

/**
 * The output latency options: JSON {ok, value: [{id, streamOnly, available,
 * latencyUs, batchUs, effectiveUs}]}. Returns the length needed.
 */
uint32_t dspi_fetch_output_latency_options(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Request output latency option `id` (1..=7). The device applies it later.
 */
bool dspi_set_output_latency(struct FfiCore *core, uint8_t id);

/**
 * The clock diagnostics packet: JSON {ok, available, raw, fields: [{name,
 * value}]}; `available` false on firmware built without them. Returns the
 * length needed.
 */
uint32_t dspi_fetch_clock_diag(struct FfiCore *core, char *buf, uint32_t len);

/**
 * The output rings' health: JSON {ok, targetFrames, targetUs, batchFrames,
 * underrunEpisodes, refusedBlocks, lowestFill, worstInputGapUs, worstUsbGapUs,
 * overBudgetSteps}, with `lowestFill` null before the first write. On firmware
 * without the status, {"ok":true,"value":null}: show no section. Returns the
 * length needed.
 */
uint32_t dspi_fetch_ring_health(struct FfiCore *core, char *buf, uint32_t len);

/**
 * The live outputs' fill, on the ring's scale where the firmware has one:
 * JSON {ok, value: [{fillPct, minPct, maxPct, band}]}, `band` being "good",
 * "warn" or "bad". Returns the length needed.
 */
uint32_t dspi_fetch_output_fills(struct FfiCore *core, char *buf, uint32_t len);

/**
 * The Stats window's fast poll, one transfer: JSON {ok, buffers: {numSpdif,
 * pdmActive, streaming, sequence, spdif: [{free, prepared, playing, fillPct,
 * minPct, maxPct}], pdm: {...}}, fills: [as dspi_fetch_output_fills] or null}.
 * Null fills mean keep the last ones. Returns the length needed.
 */
uint32_t dspi_fetch_stats_tick(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Check a `.uf2` image: JSON {ok, valid, problem, familyId, platform,
 * numBlocks, payloadBytes, firmwareVersion}. `valid` is false for a null or
 * malformed image. Returns the length needed.
 */
uint32_t dspi_uf2_inspect(const uint8_t *image, uint32_t image_len, char *buf, uint32_t len);

/**
 * Mounted bootloader drives: JSON {ok, value: [{path, platform, info}]}.
 * Returns the length needed.
 */
uint32_t dspi_bootloader_drives(char *buf, uint32_t len);

/**
 * Write a validated image to the bootloader drive at `drive_path`, whose
 * `platform` comes from `dspi_bootloader_drives` (0 RP2040, 1 RP2350). The
 * image and the drive are checked before any byte goes out. Replies in JSON
 * {ok} or {ok, code, error}, and returns the length needed. `ok` means only
 * that the write ended, or that the drive went away during it, assumed to be
 * the board rebooting: confirm with `dspi_firmware_version_matches` once the
 * DSPi is back.
 */
uint32_t dspi_flash_to_drive(const uint8_t *image,
                             uint32_t image_len,
                             const char *drive_path,
                             int8_t platform,
                             char *buf,
                             uint32_t len);

/**
 * 1 if the open device runs firmware `version` (a UF2's `firmwareVersion`),
 * 0 if not, -1 with no device open or for a null or invalid string.
 */
int8_t dspi_firmware_version_matches(struct FfiCore *core, const char *version);

/**
 * The calibration flow as it stands, from memory, with no traffic (it waits
 * for a call in flight, so keep it off the UI thread): JSON
 * {ok, available, phase, messageKey, message, warning, soakNote, ...}, the
 * fields of dspi-core's `VregCalView`. Returns the length needed.
 */
uint32_t dspi_core_vreg_cal_view(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Read the device and advance the flow, as `dspi_core_vreg_cal_view` for the
 * reply. Call about once a second while the page shows, and on every connect.
 * The next step of a run the user started may go out here, but never a save,
 * and a second call for a larger buffer does no harm. Returns the length needed.
 */
uint32_t dspi_core_vreg_cal_poll(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Open the flow: the user reached it from Advanced. Sends no write.
 */
uint8_t dspi_core_vreg_cal_open(struct FfiCore *core);

/**
 * Close the flow: the user left. Refused while a run is under way.
 */
uint8_t dspi_core_vreg_cal_close(struct FfiCore *core);

/**
 * Start a run at VREG code `target` for `soak_s` seconds. `typed` is what the
 * user typed when the view says the voltage needs the word, or null.
 */
uint8_t dspi_core_vreg_cal_start(struct FfiCore *core,
                                 uint8_t target,
                                 uint32_t soak_s,
                                 const char *typed);

/**
 * Keep a trial found on the device, for `soak_s` seconds from now.
 */
uint8_t dspi_core_vreg_cal_keep(struct FfiCore *core, uint32_t soak_s);

/**
 * Save the voltage that passed. `typed` as for `dspi_core_vreg_cal_start`.
 */
uint8_t dspi_core_vreg_cal_commit(struct FfiCore *core, const char *typed);

/**
 * End a trial, or abort a run.
 */
uint8_t dspi_core_vreg_trial_end(struct FfiCore *core);

/**
 * Manual save: `value` 0 is the build default, otherwise the flow's limits
 * and confirmation apply. `typed` as for `dspi_core_vreg_cal_start`.
 */
uint8_t dspi_core_vreg_manual_set(struct FfiCore *core, uint8_t value, const char *typed);

/**
 * Manual trial, with the flow's limits and confirmation.
 */
uint8_t dspi_core_vreg_manual_trial(struct FfiCore *core, uint8_t value, const char *typed);

/**
 * Turn the firmware's automatic raising on or off.
 */
uint8_t dspi_core_vreg_manual_auto(struct FfiCore *core, bool on);

/**
 * Forget the hang count and the last trial failure. Refused during a run.
 */
uint8_t dspi_core_vreg_manual_clear(struct FfiCore *core);

/**
 * On the demo device only: 0 a hang, 1 a requested reboot, 2 a power cycle,
 * 3 `seconds` passing on the device's clock.
 */
uint8_t dspi_core_vreg_demo_event(struct FfiCore *core, uint8_t event, uint32_t seconds);

/**
 * On the demo device only: hold it in a running revert (`on`), or let it finish.
 * While held, control-surface writes settle busy, and the save, the revert, a
 * macro fire and a learn are refused. 0 when done.
 */
uint8_t dspi_cs_demo_busy(struct FfiCore *core, bool on);

/**
 * What a page shows for one control-surface record, as JSON: `dspi_core`'s
 * `cs_describe`. `kind` is `binding`, `ir`, `step`, `page`, `display` or `group`;
 * `draft` is the record's JSON. No device I/O. Returns the bytes needed including
 * the NUL; call again with a larger buffer if that exceeds `len`.
 */
uint32_t dspi_cs_describe(struct FfiCore *core,
                          const char *kind,
                          uint32_t slot,
                          const char *draft,
                          char *buf,
                          uint32_t len);

/**
 * The record after one row's value changed, as JSON `{ok, draft}`: `dspi_core`'s
 * `cs_edit`. `change` is `{id, value}`. No device I/O. Sized as [`dspi_cs_describe`].
 */
uint32_t dspi_cs_edit(struct FfiCore *core,
                      const char *kind,
                      uint32_t slot,
                      const char *draft,
                      const char *change,
                      char *buf,
                      uint32_t len);

/**
 * A fresh binding of a component type in `slot`, on free pins, as JSON `{ok, draft}`.
 * No device I/O. Sized as [`dspi_cs_describe`].
 */
uint32_t dspi_cs_new_binding(struct FfiCore *core,
                             uint32_t slot,
                             uint8_t component,
                             char *buf,
                             uint32_t len);

/**
 * A fresh `ir`, `step` or `page` record, as JSON `{ok, draft}`. No device I/O. Sized
 * as [`dspi_cs_describe`].
 */
uint32_t dspi_cs_new_record(struct FfiCore *core, const char *kind, char *buf, uint32_t len);

/**
 * A control-surface or pin-configuration status code as a sentence, empty for
 * success. Sized as [`dspi_cs_describe`].
 */
uint32_t dspi_cs_status_text(struct FfiCore *core, uint8_t code, char *buf, uint32_t len);

/**
 * On the demo device only: the remote button an armed learn waits for was pressed.
 * True when a learn took it; false with nothing armed, or on any other device.
 */
bool dspi_cs_demo_learn(struct FfiCore *core, uint8_t protocol, uint32_t code);

/**
 * What the open board needs, read from the device now: JSON {ok, requiredMv,
 * source}. Call before entering the bootloader and pass `requiredMv` to
 * `dspi_firmware_guard_check`. No device, or an answer that cannot be
 * believed, gives `requiredMv` 0, which means unknown: so does a failed call.
 * Returns the length needed; 0 for a null handle.
 */
uint32_t dspi_firmware_guard_board(struct FfiCore *core, char *buf, uint32_t len);

/**
 * May this image go on this board? `board_required_mv` comes from
 * `dspi_firmware_guard_board`: 1150 not at risk, above that at risk, anything
 * else unknown. Pass 0 for a board already in the bootloader. `typed` is what
 * the user typed, null or "" if nothing yet. JSON {ok, allowed, decision,
 * reason, message, confirmationPhrase, imageMv, requiredMv}; `decision` is
 * `refused`, `needsConfirmation`, `confirmed` or `clear`, and `reason` is
 * `imageInvalid`, `noRisk`, `imageUnknown`, `imageLower` or `boardUnknown`.
 * Flash only on `allowed`. Returns the length needed.
 */
uint32_t dspi_firmware_guard_check(const uint8_t *image,
                                   uint32_t image_len,
                                   uint16_t board_required_mv,
                                   const char *typed,
                                   char *buf,
                                   uint32_t len);

/**
 * `dspi_flash_to_drive` behind `dspi_firmware_guard_check`, with the same
 * arguments as each. Nothing is written unless the guard allows it: a blocked
 * image replies {ok: false, code: "firmware_guard", error}. Returns the length
 * needed.
 */
uint32_t dspi_flash_to_drive_guarded(const uint8_t *image,
                                     uint32_t image_len,
                                     const char *drive_path,
                                     int8_t platform,
                                     uint16_t board_required_mv,
                                     const char *typed,
                                     char *buf,
                                     uint32_t len);

/**
 * Answer a fetch: the HTTP status and body, as received, for any status.
 * `retry_after_s`, `rate_limit_remaining` and `rate_limit_reset` (Unix seconds) are
 * the `Retry-After`, `X-RateLimit-Remaining` and `X-RateLimit-Reset` headers, -1 if
 * absent. The body is copied. Does nothing for a null sink.
 */
void dspi_autoeq_fetch_respond(struct AutoEqFetchSink *sink,
                               uint16_t status,
                               const uint8_t *body,
                               uint32_t body_len,
                               int64_t retry_after_s,
                               int64_t rate_limit_remaining,
                               int64_t rate_limit_reset);

/**
 * Say that no answer came (no network, a timeout), in words for the user.
 * Does nothing for a null sink.
 */
void dspi_autoeq_fetch_fail(struct AutoEqFetchSink *sink, const char *message);

/**
 * The database at `db_path`, for the "Update Database" dialog: JSON {ok,
 * hasUserDatabase, problem, version, generatedAt, entryCount}. Reads the file; off
 * the UI thread. Returns the length needed.
 */
uint32_t dspi_autoeq_database_info(const char *db_path, char *buf, uint32_t len);

/**
 * Replace the database at `db_path` with a file's bytes, once they are known to be
 * a database with at least one profile; otherwise the file is left alone. JSON as
 * `dspi_autoeq_database_info`, or a failure. `buf` needs [`AUTOEQ_REPLY_MIN`] bytes;
 * with less, this returns that minimum and does nothing (module docs). Otherwise
 * returns the reply's length.
 */
uint32_t dspi_autoeq_import(const char *db_path,
                            const uint8_t *data,
                            uint32_t data_len,
                            char *buf,
                            uint32_t len);

/**
 * Download a ready-made database from `url` and replace the one at `db_path`, once
 * it is known to be one. Blocks for the request, calling `callback` on this thread;
 * off the UI thread. JSON as `dspi_autoeq_import`. `buf` needs [`AUTOEQ_REPLY_MIN`]
 * bytes; with less, this returns that minimum and does nothing: no fetch, no file
 * change (module docs). Otherwise returns the reply's length.
 */
uint32_t dspi_autoeq_update(const char *db_path,
                            const char *url,
                            AutoEqFetchCallback callback,
                            void *user_data,
                            char *buf,
                            uint32_t len);

/**
 * Reset to Built-in: remove the database at `db_path`. JSON {ok, value}: `value`
 * true if there was one. The host then goes back to its own bundled copy. `buf` needs
 * [`AUTOEQ_REPLY_MIN`] bytes; with less, this returns that minimum and does nothing
 * (module docs). Otherwise returns the reply's length.
 */
uint32_t dspi_autoeq_reset_to_builtin(const char *db_path, char *buf, uint32_t len);

/**
 * What a rebuild will reach for and write, as text to show before starting one.
 * Returns the length needed; 0 for a null or invalid `db_path`.
 */
uint32_t dspi_autoeq_rebuild_warning(const char *db_path, char *buf, uint32_t len);

/**
 * Start rebuilding the database at `db_path` from GitHub, and return at once.
 * `callback` runs on the rebuild's threads (module docs), and it and `user_data` must
 * stay valid until `dspi_autoeq_rebuild_free` returns. Free the handle with that.
 * Null for a null or invalid `db_path` or a null callback.
 */
struct AutoEqRebuildHandle *dspi_autoeq_rebuild_start(const char *db_path,
                                                      AutoEqFetchCallback callback,
                                                      void *user_data);

/**
 * The newest progress: JSON {ok, fraction, status, finished, succeeded, code,
 * retryAfterS, entries, failedProfiles, failedListings, skippedProfiles}. `succeeded`
 * means the database was written; on a failure the file was left as it was, and `code`
 * says why (`rate_limited`, `cancelled`, `no_profiles`, `too_many_failures`, ...).
 * Does not block. Returns the length needed; 0 for a null handle.
 */
uint32_t dspi_autoeq_rebuild_poll(struct AutoEqRebuildHandle *handle, char *buf, uint32_t len);

/**
 * Stop at the next batch of profiles; nothing is written. Does not block: keep
 * polling until `finished`. Does nothing for a null handle.
 */
void dspi_autoeq_rebuild_cancel(struct AutoEqRebuildHandle *handle);

/**
 * Cancel if still running, wait until the callback can no longer be called, and free
 * the handle. Blocks for the requests in flight, so it deadlocks if the callback is
 * waiting on this thread; poll until `finished` first to avoid blocking at all. Do not
 * call from inside the callback. Null is ignored.
 */
void dspi_autoeq_rebuild_free(struct AutoEqRebuildHandle *handle);

/**
 * What to tell the user about a Link phase, in JSON: {ok, key, phase, text,
 * actionKey, action}, or {ok:false, code:"invalid", error} for a `phase` that is
 * no phase. `phase` is the name `dspi_link_status` reports. `pin_source` is its
 * `pinSource`; it matters only to `needs_pairing`, and null reads as `window`.
 * `key` is what to localise by: the phase's name, or `needs_pairing.window` or
 * `needs_pairing.fixed`. `actionKey` and `action` are null, or a button the phase
 * must show: `reconnecting`'s calls `dspi_link_close`.
 * Returns the bytes needed including the NUL, 0 for a null `phase` or a panic.
 */
uint32_t dspi_link_phase_text(const char *phase, const char *pin_source, char *buf, uint32_t len);

/**
 * The whole wording table in JSON, every key once: {ok, value:[{key, phase, text,
 * actionKey, action}]}. Returns the bytes needed including the NUL, 0 for a panic.
 */
uint32_t dspi_link_phase_texts(char *buf, uint32_t len);

/**
 * The release notes for the platform this library was compiled for, as a JSON
 * document: [{version, headline, items}], newest first; no `ok` wrapper. Returns the bytes needed including the NUL, 0 for
 * a panic.
 */
uint32_t dspi_onboarding_whats_new_json(char *buf,
                                        uint32_t len);

/**
 * The Getting Started wizard's data for the platform this library was compiled
 * for, as a JSON document; no `ok` wrapper. `dspi_core::link_text` describes it.
 * Returns the bytes needed including the NUL,
 * 0 for a panic.
 */
uint32_t dspi_onboarding_getting_started_json(char *buf, uint32_t len);

/**
 * The About table, as a JSON document with no `ok` wrapper: {draft, credit_lines:
 * [{id, text}], makers: [{id, name, url, made}], links: [{id, title, detail, url}],
 * credits: [{id, name, what, url?}]}. The wording is a draft while `draft` is true.
 * Returns the bytes needed including the NUL, 0 for a panic.
 */
uint32_t dspi_about_json(char *buf, uint32_t len);

/**
 * Start looking for hubs on the local network, replacing any browse running.
 * Returns at once; false only with a null handle, in a build without the
 * feature, or when a thread cannot start. A network failure shows in
 * `dspi_link_browse_hubs`'s `error`, and browsing is tried again by itself.
 *
 * `own_hub_id` is this app's own hub, which is not listed; null or "" for none.
 * `callback` (may be null) is a wake-up when the list or state changes. It runs
 * on the browser's thread with `user_data`, which must allow that: schedule work
 * and return. It may call any `dspi_link_browse_*` function.
 */
bool dspi_link_browse_start(struct FfiCore *core,
                            void (*callback)(void *user_data),
                            void *user_data,
                            const char *own_hub_id);

/**
 * Stop looking and forget the hubs. Waits for a callback in progress, so none is
 * in progress or to come afterwards and `user_data` can go, unless called from
 * the callback itself. Also happens in `dspi_core_free`.
 */
void dspi_link_browse_stop(struct FfiCore *core);

/**
 * The browse as JSON: `{"ok":true,"browsing":bool,"error":text or null,"hubs":[{"id",
 * "name","kind","auth","deviceCount","serials","host","port","path","url",
 * "addresses"}]}`, sorted by name. Not browsing and no hubs when none runs. `url`
 * goes to the connect function. Returns the length needed.
 */
uint32_t dspi_link_browse_hubs(struct FfiCore *core, char *buf, uint32_t len);

/**
 * The hub with this id (any case) as last heard: `{"ok":true,"hub":{...}}`, fields
 * as in `dspi_link_browse_hubs`, or `"hub":null` when it is not found. A null or
 * invalid id is not found. Returns the length needed.
 */
uint32_t dspi_link_browse_resolve(struct FfiCore *core,
                                  const char *hub_id,
                                  char *buf,
                                  uint32_t len);

/**
 * Point the current Link session at the address its hub is announced at now; a
 * session waiting to reconnect dials at once. Call it when the browse changes
 * while the session is reconnecting, with the id from the session's hello. False,
 * with nothing changed, when that hub is not found.
 */
bool dspi_link_browse_reresolve(struct FfiCore *core, const char *hub_id);

/**
 * Ask the network whether this hub is still there, for when dialling it fails. One
 * that does not answer leaves the list within seconds, and the callback runs.
 * Returns at once.
 */
void dspi_link_browse_verify(struct FfiCore *core, const char *hub_id);

/**
 * Open a Link session to `url` (`dspi_link_ws_url`), replacing any previous
 * one, and reply with the hub's hello: JSON {ok, hubId, hubName, hubKind,
 * hubVersion, protoMinor, auth, pinSource, needsPairing, caps, maxPayload,
 * maxInflight, tokenRefused}. Blocks up to about 15 s. All strings are
 * required.
 *
 * `token`: the token stored for this hub, "" = none. `expected_hub_id`: the
 * id it was stored under. With it, a token goes out only after the hello
 * has named that hub, and another hub at the address gets code `wrong_hub`
 * having seen no token. "" = not known: the token goes to whichever hub
 * answers. Forget a stored token only when `tokenRefused` says so.
 *
 * When `needsPairing`, ask for the PIN and call `dspi_link_pair`. From here
 * on the core keeps the session up: do not redial, do not queue writes.
 * Returns the length needed; see the module's rule on short buffers.
 */
uint32_t dspi_link_connect(struct FfiCore *core,
                           const char *url,
                           const char *client_name,
                           const char *app_version,
                           const char *token,
                           const char *expected_hub_id,
                           char *buf,
                           uint32_t len);

/**
 * Pair with the PIN the user typed: JSON {ok, token}; store the token
 * against the hub id ("" when the hub issued none). Code `wrong_pin`: ask
 * again. `rate_limited`: the hub refuses for a minute. `timeout`: the hub
 * may still have accepted it, and `LINK_EVENT_TOKEN_ISSUED` then delivers
 * the token. Blocks. Returns the length needed; see the module's rule on
 * short buffers.
 */
uint32_t dspi_link_pair(struct FfiCore *core, const char *pin, char *buf, uint32_t len);

/**
 * The hub's devices (empty before authentication): JSON {ok, value:
 * [{handle, serial, name, fw, fwBeta, platform, state, link, lockedBy}]}.
 * Returns the length needed.
 */
uint32_t dspi_link_devices(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Where the session stands: JSON {ok, connected, ready, session, role,
 * denied: [{request, dir}], closed, closeCode, closeReason, phase,
 * reconnectAttempt, reconnectInMs, pinSource, tokenRefused}. `phase` is
 * what to tell the user: `idle`, `needs_pairing`, `no_device`,
 * `choose_device`, `bound`, `reconnecting`, `closed` or `refused`. No
 * blocking beyond the core lock. Returns the length needed.
 */
uint32_t dspi_link_status(struct FfiCore *core, char *buf, uint32_t len);

/**
 * Bind the core to the hub's device `handle` (from `dspi_link_devices`), and
 * reply JSON {ok}. Then `dspi_fetch_all`, as for USB. The core binds it again
 * by itself after a reconnect. Blocks. Returns the length needed; see the
 * module's rule on short buffers.
 */
uint32_t dspi_link_select_device(struct FfiCore *core,
                                 uint32_t handle,
                                 const char *serial,
                                 char *buf,
                                 uint32_t len);

/**
 * Close the session, drop a device bound to it and stop any reconnecting:
 * how an app leaves a hub, and the lost-connection banner's abort button.
 * Safe on a UI thread and inside a [`LinkEventCallback`]: it returns within
 * about 100 ms whatever the link does. Quiet: no `LINK_EVENT_CLOSED`.
 */
void dspi_link_close(struct FfiCore *core);

/**
 * Try to reconnect now instead of waiting out the backoff (the network is
 * back). A no-op unless reconnecting.
 */
void dspi_link_retry_now(struct FfiCore *core);

/**
 * The hub answers at a new address: reconnect there from now on. False for
 * a null handle, or a null or non-UTF-8 `url`. An address that cannot be
 * dialled is logged and ignored, and this still returns true.
 */
bool dspi_link_set_url(struct FfiCore *core, const char *url);

/**
 * Register the session events callback; NULL clears it. Replacing or
 * clearing waits for a call in progress on another thread, so `user_data`
 * may go right after it returns. False for a null handle, and when called
 * from inside the callback, where it would wait for itself. `dspi_core_free`
 * clears it too, and must not be called from inside it.
 */
bool dspi_link_set_listener(struct FfiCore *core,
                            void (*callback)(uint8_t event,
                                             int32_t code,
                                             const char *text,
                                             const char *token,
                                             void *user_data),
                            void *user_data);

/**
 * Parse a hub address the user typed (`host`, `host:port`, `[v6]:port`):
 * JSON {ok, host, port}. Returns the length needed; 0 for a panic.
 */
uint32_t dspi_link_parse_address(const char *text, char *buf, uint32_t len);

/**
 * The WebSocket URL for a hub, as plain text. `path` null or "" is the
 * default (`/dspi/v1`). Returns the length needed; 0 for a null or non-UTF-8
 * `host` or a non-UTF-8 `path`.
 */
uint32_t dspi_link_ws_url(const char *host,
                          uint16_t port,
                          const char *path,
                          char *buf,
                          uint32_t len);

/**
 * `GET /dspi/v1/info`, for a hub added by address: JSON {ok, hubId, hubName,
 * hubKind, auth, protoMinor, wsPath, serials}. Blocks up to a few seconds.
 * Returns the length needed; 0 for a panic. A short buffer means asking the
 * hub again.
 */
uint32_t dspi_link_fetch_info(const char *host, uint16_t port, char *buf, uint32_t len);

/**
 * The DSPi control ports this host can see: JSON {ok, value: [name]}. Lists
 * MIDI ports, so keep it off a UI thread and call it at most once a second.
 * Returns the length needed; 0 for a panic.
 */
uint32_t dspi_midi_ports(char *buf, uint32_t len);

/**
 * Open a DSPi through its USB MIDI control ports. `name` is one of
 * `dspi_midi_ports`' names; null or "" takes the only port. Replaces any
 * open device; follow it with `dspi_fetch_all`. Blocks for the connect
 * sequence. False for a null handle, a non-UTF-8 `name`, no such port, a
 * choice of several, or when the device does not answer.
 */
bool dspi_open_midi(struct FfiCore *core, const char *name);

/**
 * Create a hub's handle, with no hub running. Free it with `dspi_hub_free`. Null if
 * creating it panicked.
 */
struct FfiHub *dspi_hub_new(void);

/**
 * Stop a running hub and destroy the handle. Null is ignored. Blocks as
 * `dspi_hub_stop` does. The last callback, `HUB_EVENT_STOPPED`, has returned by the time
 * this does, so `user_data` may go then. Refused from inside the callback, with a log
 * line: the handle stays valid and nothing is freed.
 */
void dspi_hub_free(struct FfiHub *hub);

/**
 * Register the events callback, which stays for later runs; NULL clears it. Replacing or
 * clearing waits for a call in progress on another thread, so `user_data` may go right
 * after it returns. False for a null handle, and when called from inside the callback,
 * where it would wait for itself.
 */
bool dspi_hub_set_listener(struct FfiHub *hub, void (*callback)(uint8_t event,
                                                                int32_t code,
                                                                const char *text,
                                                                void *user_data), void *user_data);

/**
 * What the store in `store_dir` holds, with or without a hub on it: JSON {ok, exists,
 * hubId, name, access, defaultPort, tokensRevokedIfPin, tokensRevokedIfOpen, clients:
 * [{cid, name, role, created, lastSeen, online}]}. Creates nothing and changes nothing.
 *
 * `access` is the mode it last ran in (`pin`, `none`) and null before the first start;
 * `name` is null if never named; `hubId` is null when `exists` is false. A store that
 * cannot be parsed reads as not existing: the next start sets it aside.
 *
 * **`tokensRevokedIfPin` and `tokensRevokedIfOpen`** are how many paired clients a start
 * in that mode would forget, and must pair again. Warn the user when it is not 0, since
 * it cannot be undone. `created` and `lastSeen` are seconds since the epoch, `lastSeen`
 * may be null, and `online` is false here. Returns the length needed; 0 for a panic.
 */
uint32_t dspi_hub_saved_settings(const char *store_dir, char *buf, uint32_t len);

/**
 * Start the hub: its threads and its socket, then, with `HUB_OPT_USB` and without
 * `HUB_OPT_APP`, the first bus scan. Replies JSON {ok, hubId, name, port, access,
 * tokensRevoked}. Blocks. If it fails, nothing is left running.
 *
 * `name`: "" takes the stored one or a default; another is cleaned and stored.
 * `store_dir` is the hub's own directory, created if need be: its id, clients and device names. Two hubs must not
 * share one. `port` 0 lets the OS choose, and the reply says which. `access` is a
 * `HUB_ACCESS_*`, and `options` are `HUB_OPT_*`.
 *
 * **A change of `access` from the store's last run revokes every token.** `tokensRevoked`
 * says how many; `dspi_hub_saved_settings` says so beforehand. Code `running` if a hub
 * already is: stop it first. A port in use is code `io`.
 *
 * Returns the length needed; see the module's rule on short buffers.
 */
uint32_t dspi_hub_start(struct FfiHub *hub,
                        const char *name,
                        const char *store_dir,
                        uint16_t port,
                        uint8_t access,
                        uint32_t options,
                        char *buf,
                        uint32_t len);

/**
 * Stop the hub. Clients are told (close code 4003), queued commands are answered, every
 * thread is joined and the devices are let go when this returns. An app on it gets its
 * direct path back, and its device reopened. Blocks up to a few seconds. True also when
 * no hub was running; a concurrent caller waits for the first. False for a null handle,
 * and from inside the callback, which it would have to wait for.
 */
bool dspi_hub_stop(struct FfiHub *hub);

/**
 * Put the app's core on the running hub, so that its USB devices come through it. The
 * device it holds is closed, claimed by the hub and reopened, so the mirror is read
 * afresh, and a flow in progress on it fails, as with an unplug. A demo, MIDI or Link
 * connection stays as it is. Starts the bus's scans. Blocks. False for a null handle, no
 * hub running, a second app, or inside the callback, with a log line.
 *
 * `dspi_hub_stop` undoes it. Stop the hub before `dspi_core_free`.
 */
bool dspi_hub_attach_app(struct FfiHub *hub, struct FfiCore *core);

/**
 * Give the running hub a demo device to serve, for trying sharing with no hardware.
 * Blocks for its identity reads. Returns its handle, or -1 for a null handle, no hub
 * running, a demo device already attached, or inside the callback, with a log line.
 */
int32_t dspi_hub_attach_demo(struct FfiHub *hub);

/**
 * Where the hub stands: JSON {ok, running}, and while it runs {hubId, name, port, access,
 * connections, inaccessible, tokensRevoked, pairingOpen, pairingExpiresInMs}. `access` is
 * `pin` or `none`, as clients see it. `connections` counts sockets, signed in or not.
 * `inaccessible` is devices on the bus that could not be opened at the last scan: another
 * program, or a permission. `tokensRevoked` is what this run's start cost. Quick, and
 * allowed in the callback. Returns the length needed.
 */
uint32_t dspi_hub_status(struct FfiHub *hub, char *buf, uint32_t len);

/**
 * The hub's devices, online and in their grace: JSON {ok, value: [{handle, serial, name,
 * fw, fwBeta, platform, outputs, state, link, lockedBy}]}, empty with no hub running.
 * Quick, and allowed in the callback. Returns the length needed.
 */
uint32_t dspi_hub_devices(struct FfiHub *hub, char *buf, uint32_t len);

/**
 * The paired clients: JSON {ok, value: [{cid, name, role, created, lastSeen, online}]}.
 * `role` is `viewer`, `control` or `admin`; `created` and `lastSeen` are seconds since the
 * epoch, `lastSeen` may be null; `online` means it has a session now. Code `not_running`
 * with no hub: `dspi_hub_saved_settings` lists them then. An open hub lists none, as its
 * clients do not pair. Quick, and allowed in the callback. Returns the length needed.
 */
uint32_t dspi_hub_clients(struct FfiHub *hub, char *buf, uint32_t len);

/**
 * Open the pairing window, replacing an open one, whose PIN then stops working: JSON
 * {ok, pin, expiresInMs}. Show the PIN to the user and to nobody else, with the time it
 * has left. A client's right PIN ends the window (`HUB_EVENT_SESSION_OPENED`), and so do
 * five wrong ones. Code `not_running`, or `open_access` if this hub admits anyone anyway,
 * or `io` if the system has no random numbers. Returns the length needed; see the
 * module's rule on short buffers.
 */
uint32_t dspi_hub_begin_pairing(struct FfiHub *hub, char *buf, uint32_t len);

/**
 * Close the pairing window, if one is open. False for a null handle, no hub running, or
 * inside the callback.
 */
bool dspi_hub_cancel_pairing(struct FfiHub *hub);

/**
 * Forget a paired client: its token stops working and its connections close at once with
 * code 4002, which clients do not reconnect from. It would have to pair again. Writes the
 * store. False for a null handle, no hub running, no such client, or inside the callback.
 */
bool dspi_hub_revoke(struct FfiHub *hub, uint32_t cid);

/**
 * Change a paired client's role, `viewer`, `control` or `admin`: its next command is
 * judged by the new one. Writes the store. False for a null handle, no hub running, no
 * such client, another role, or inside the callback.
 */
bool dspi_hub_set_role(struct FfiHub *hub, uint32_t cid, const char *role);

#endif  /* DSPI_CORE_H */
